/* AI in Motion — MLOps & ML Engineering track (deep dives, 10+ minutes each). © Janin A Apurba, CSE, AUST */
const S = (kit, chapter, o, say) => Object.assign({ kit, chapter }, o, { say });

module.exports = [
  {
    slug: 'what-is-mlops-and-the-ml-lifecycle', title: 'What is MLOps? The Machine Learning Lifecycle', track: 'mlops', level: 'Beginner', deep: true,
    summary: 'Why a good model in a notebook is only the start: the ML lifecycle, hidden technical debt, training–serving skew, MLOps maturity levels, the tool landscape and the principles that keep models working in production.',
    scenes: [
      S('title', 'Introduction', { title: 'What is MLOps?', sub: 'From a notebook to a system that keeps working', track: 'MLOps & Engineering' }, 'Training a model that scores well in a notebook is exciting, but it is only the beginning. A model must be deployed, monitored, retrained and trusted by real users for months or years. MLOps is the discipline that makes that possible. This deep dive gives you the big picture.'),
      S('definition', 'MLOps', { term: 'MLOps', def: 'Practices and tools for reliably building, deploying, monitoring and improving machine-learning systems in production — DevOps extended to data and models.', eg: 'versioned data, automated pipelines, tested models, monitored predictions' }, 'MLOps is a set of practices and tools for reliably building, deploying, monitoring and improving machine learning systems in production. It extends the ideas of DevOps, which transformed software delivery, to the two things that make machine learning different: data and models.'),
      S('compare', 'Notebook vs production', { head: 'The gap between a notebook and production', left: { title: 'In the notebook', items: ['A fixed, clean dataset', 'Run once, by hand', 'Success = a good test score'], color: 'cyan' }, right: { title: 'In production', items: ['Data changes every day', 'Runs continuously, automatically', 'Success = reliable value for users'], color: 'lime' } }, 'The gap is large. In a notebook, the dataset is fixed and clean, the code runs once by hand, and success means a good test score. In production, data changes every day, everything must run automatically and continuously, and success means reliable value for users, month after month.'),
      S('debt', 'Hidden technical debt', {}, 'A famous 2015 paper from Google, Hidden Technical Debt in Machine Learning Systems, drew this picture. The machine learning code is the small box in the middle. Around it sit configuration, data collection and verification, feature extraction, resource management, serving infrastructure and monitoring, and that is where most of the work lives.'),
      S('cycle', 'The ML lifecycle', { head: 'The machine-learning lifecycle', steps: ['Frame the problem', 'Collect & prepare data', 'Train & evaluate', 'Deploy', 'Monitor', 'Improve'], desc: ['What decision will the model support? How is success measured?', 'Gather, label, validate and version the data.', 'Experiment, track runs, compare against baselines.', 'Package and release safely.', 'Watch data, predictions and outcomes.', 'Retrain, fix and iterate.'] }, 'Machine learning work is a cycle, not a straight line. Frame the problem and define success. Collect, label and validate data. Train and evaluate against baselines. Deploy safely. Monitor data, predictions and outcomes. Then improve, which usually sends you back to the data. MLOps tries to make every turn of this cycle faster and safer.'),
      S('compare', 'DevOps vs MLOps', { head: 'Why ML needs more than DevOps', left: { title: 'Traditional software', items: ['Behaviour defined by code', 'Tests check code logic', 'Works until the code changes'], color: 'blue' }, right: { title: 'Machine learning', items: ['Behaviour learned from data + code', 'Also test data and model quality', 'Can decay even when nothing is changed'], color: 'lime' } }, 'Why is DevOps not enough? In traditional software, behaviour is defined by code, and tests check that logic. In machine learning, behaviour is learned from data and code together, so we must also test the data and the model’s quality. And a model can silently decay even when nobody changes a line of code.'),
      S('definition', 'Changing anything changes everything', { term: 'CACE principle', def: '“Changing Anything Changes Everything”: models entangle their inputs, so altering one feature, a data source or a threshold can shift behaviour everywhere.', eg: 'an upstream team renames a category and the model’s accuracy quietly drops' }, 'The same paper named the CACE principle: changing anything changes everything. Models entangle their inputs, so altering one feature, one data source or one threshold can shift behaviour everywhere. An upstream team renaming a product category can quietly degrade a model that nobody touched.'),
      S('question', 'Pause and think', { q: 'A model scored 95% accuracy on the test set, but only about 80% after launch. Name three likely causes.', a: 'Training–serving skew (features computed differently live), data drift (live data differs from training data), and leakage in the original evaluation (the test score was too optimistic).' }, 'Pause and think. A model scored ninety five percent accuracy on its test set, but only about eighty percent after launch. What might have happened? Common causes are features computed differently in production, live data that differs from the training data, and leakage that made the original test score too optimistic.'),
      S('question', 'Pause and think', { q: 'You add one new feature to a model. Following the CACE principle, what else must you re-check?', a: 'Everything: the importance and behaviour of existing features, performance on every segment, thresholds, latency, and any downstream systems that consume the predictions.' }, 'Pause and think. You add a single new feature to a model. Following the changing anything changes everything principle, what should you re check? Everything: how existing features behave, performance on every segment, decision thresholds, latency, and any downstream systems that consume the predictions.'),
      S('definition', 'Training–serving skew', { term: 'Training–serving skew', def: 'A mismatch between how features are computed during training and at prediction time — different code, different data freshness, different defaults.', eg: 'training uses “average spend over 30 days” from a batch job; serving computes it over 7 days' }, 'One of the most common failures is training serving skew: features computed one way during training and another way at prediction time. Perhaps training used a thirty day average from a batch job, while the live service computes a seven day average. The model sees inputs it was never trained on, and quality drops.'),
      S('flow', 'Who is involved', { head: 'The people behind an ML system', nodes: [['pm', 'Product owner', 640, 205, 'amber', 'defines success'], ['de', 'Data engineer', 250, 350, 'cyan', 'pipelines & quality'], ['ds', 'Data scientist', 640, 350, 'violet', 'experiments & models'], ['mle', 'ML engineer', 1030, 350, 'lime', 'production & serving'], ['sre', 'Platform / SRE', 640, 510, 'pink', 'infrastructure & reliability']], edges: [['pm', 'ds', 'goals'], ['de', 'ds', 'clean data'], ['ds', 'mle', 'model'], ['mle', 'sre', 'deploy'], ['sre', 'de', 'monitoring signals', 60]], steps: ['The product owner defines the goal and the metric', 'Data engineers deliver clean, reliable data', 'Data scientists hand over a validated model', 'ML engineers deploy it on shared infrastructure', 'Monitoring feeds back into the data pipelines'] }, 'Many people are involved. A product owner defines the goal and how success is measured. Data engineers build reliable pipelines. Data scientists run experiments and produce models. Machine learning engineers turn them into production services, and platform engineers keep the infrastructure reliable. MLOps is as much about these handoffs as about tools.'),
      S('table', 'Maturity levels', { head: 'MLOps maturity (after Google Cloud’s levels)', cols: ['Level', 'What it looks like', 'Typical pain'], widths: [0.7, 2, 1.6], rows: [['0 — manual', 'notebooks, hand-run scripts, rare manual deploys', 'slow, error-prone, unreproducible'], ['1 — pipeline automation', 'automated training pipeline, continuous training on new data', 'pipeline changes still manual'], ['2 — CI/CD automation', 'pipelines themselves tested and deployed automatically', 'requires investment and discipline']] }, 'Google Cloud describes three maturity levels. At level zero everything is manual: notebooks, hand run scripts and rare deployments. At level one, a training pipeline is automated so models retrain on new data. At level two, the pipelines themselves are built, tested and deployed automatically, just like application code.'),
      S('definition', 'Start with a baseline', { term: 'Baselines first', def: 'Before any ML, measure a simple heuristic or a simple model. Ship the simplest thing that works, with the pipeline around it, then iterate.', eg: '“predict last week’s value” or logistic regression often sets a surprisingly high bar' }, 'Before building anything complex, measure a baseline: a simple rule, such as predicting last week’s value, or a simple model like logistic regression. Ship the simplest thing that works, together with the pipeline around it, and iterate from there. Baselines often set a surprisingly high bar.'),
      S('pipeline', 'Level 0', { head: 'Level 0: the manual process', steps: ['Notebook', 'Export model', 'Email / upload', 'Manual deploy', 'Hope'], desc: ['Explore and train interactively.', 'Save a model file by hand.', 'Hand it over to another team.', 'Someone wires it into an application.', 'No monitoring, retraining is a new project.'] }, 'Level zero is where most teams start. A data scientist trains in a notebook, exports a model file and hands it to another team, who wire it into an application by hand. There is no monitoring, and retraining becomes a whole new project. It works for a first proof of concept, but it does not scale.'),
      S('tracking', 'Tracking experiments', {}, 'A first step up is tracking every experiment. Each run records its parameters, metrics, code version and resulting model, so the best run can be found and reproduced later. Here five runs with different learning rates and dropout are compared, and the best one is clear.'),
      S('ci', 'Automated pipelines', {}, 'Higher maturity means automation. Every change triggers a pipeline that tests code and data, retrains the model, evaluates it against quality gates, registers it and deploys it gradually. The same steps run the same way every time, which makes releases boring, and in operations, boring is good.'),
      S('lineage', 'Versioning everything', {}, 'Reproducibility requires versioning more than code. Data versions, code versions, experiment runs and model versions are linked, so for any model in production you can trace exactly which code, which data and which settings produced it, and rebuild it on demand.'),
      S('docker', 'Packaging', {}, 'Models must be packaged so they run identically everywhere. Containers bundle the operating system, libraries, model file and serving code into one image. The same image runs on a laptop, a cloud machine or a Kubernetes cluster, ending the classic excuse, it works on my machine.'),
      S('serving', 'Serving', {}, 'Once packaged, a model is served, often behind an API. Real traffic rises and falls through the day, so an autoscaler adds and removes replicas. When load spikes faster than capacity, latency rises above the service level objective, which is exactly what monitoring must catch.'),
      S('monitor', 'Monitoring', {}, 'Monitoring watches more than servers. Here system metrics like latency and error rate look perfectly healthy, yet on day eighteen an upstream change breaks a feature. The distribution of predictions shifts immediately, and accuracy, measured days later when labels arrive, confirms the damage.'),
      S('drift', 'Data drift', {}, 'One reason monitoring matters is data drift. Here the live distribution of a feature slowly moves away from the training distribution over ten weeks. A drift score crosses a warning level and then an alert level, prompting investigation and retraining before accuracy quietly collapses.'),
      S('definition', 'Feedback loops', { term: 'Feedback loops', def: 'A model’s predictions influence the data it is later retrained on — a recommender that only shows popular items only learns about popular items.', eg: 'loops can entrench bias; keep some exploration and hold-out traffic' }, 'Models can also influence their own future training data. A recommender that only shows popular items only collects feedback about popular items, so it grows ever more convinced they are the best. Such feedback loops can entrench bias, which is why teams keep some exploration and hold out traffic.'),
      S('question', 'Pause and think', { q: 'A loan model rejects applicants it considers risky, so their repayment is never observed. What problem does this create for retraining?', a: 'Selection bias from a feedback loop: labels exist only for approved applicants, so the model never learns whether rejected groups would have repaid. Randomised exploration or careful reject inference is needed.' }, 'Pause and think. A loan model rejects applicants it considers risky, so we never see whether they would have repaid. What does that do to retraining? The new training data contains only approved applicants, so the model can never learn it was wrong about the rejected groups. This selection bias needs deliberate exploration or careful correction.'),
      S('bullets', 'Principles', { head: 'Core MLOps principles', items: ['Automate — pipelines over manual steps', 'Version — code, data, models and configuration', 'Test — code, data and model quality', 'Monitor — data, predictions and outcomes', 'Iterate — small, reversible changes'] }, 'A few principles run through all of MLOps. Automate repeatable work with pipelines. Version code, data, models and configuration. Test the data and the model, not only the code. Monitor data, predictions and business outcomes. And make small, reversible changes, so that mistakes are cheap.'),
      S('table', 'Tool landscape', { head: 'A typical open-source MLOps toolbox', cols: ['Need', 'Examples'], widths: [1, 2.4], rows: [['Code & data versioning', 'Git, DVC, lakeFS'], ['Experiment tracking & registry', 'MLflow, Weights & Biases'], ['Pipelines & orchestration', 'Airflow, Kubeflow Pipelines, Prefect'], ['Serving', 'FastAPI, BentoML, KServe, NVIDIA Triton'], ['Monitoring', 'Prometheus + Grafana, Evidently']] }, 'Many tools fill these roles. Git and DVC version code and data. MLflow and Weights and Biases track experiments and register models. Airflow, Kubeflow and Prefect orchestrate pipelines. FastAPI, BentoML, KServe and Triton serve models, and Prometheus, Grafana and Evidently monitor them. Principles matter more than particular tools.'),
      S('code', 'A tidy project', { head: 'A reproducible project layout', file: 'project/', lines: ['project/', '  data/            # raw & processed data, tracked with DVC', '  src/', '    features.py    # ONE feature definition for training and serving', '    train.py       # reads config, logs runs to MLflow', '    evaluate.py    # quality gates: fails the build if too weak', '    serve.py       # FastAPI app that loads the registered model', '  tests/           # unit, data and model tests', '  configs/         # hyperparameters as files, not code edits', '  Dockerfile       # the runtime environment', '  requirements.txt # pinned library versions'], hl: [1, 3, [4, 6], [7, 10]], notes: ['Data is versioned, not just copied around', 'One shared feature module prevents training–serving skew', 'Training, evaluation and serving are separate, scriptable steps', 'Tests, configs, container and pinned dependencies make runs reproducible'] }, 'Good habits start with project structure. Data is versioned with DVC. A single feature module is shared by training and serving, preventing skew. Training, evaluation and serving are separate scripts that pipelines can run. Tests, configuration files, a Dockerfile and pinned dependencies make every run reproducible.'),
      S('definition', 'Documentation', { term: 'Model cards and datasheets', def: 'Short documents describing a model’s intended use, training data, evaluation results (including by subgroup), limitations and ethical considerations.', eg: 'they make hand-offs, audits and responsible use much easier' }, 'Documentation is part of the system. Model cards and datasheets for datasets describe what a model is for, what data it was trained on, how it performs, including for different groups of people, and what its limitations are. They make hand offs, audits and responsible use far easier.'),
      S('definition', 'Cost awareness', { term: 'Cost as a first-class metric', def: 'Track the cost of training runs, GPU hours, storage and per-prediction serving alongside accuracy.', eg: 'a 1% accuracy gain may not justify 10× serving cost' }, 'Cost is a first class metric in production. Track the cost of training runs, GPU hours, storage and each prediction served, alongside accuracy. A one percent accuracy gain might not justify ten times the serving cost, and cheaper models can often be deployed more widely.'),
      S('question', 'Pause and think', { q: 'Your team is at maturity level 0. What is the single most valuable first step?', a: 'Usually: make training reproducible and tracked (versioned data + scripted training + experiment tracking), then add basic monitoring. Automation builds on these foundations.' }, 'Pause and think. Your team is at maturity level zero. What single step gives the most value first? Usually, make training reproducible: script it, version the data and track experiments. Then add basic monitoring. Full automation is much easier once these foundations exist.'),
      S('bullets', 'Common pitfalls', { head: 'Common MLOps pitfalls', items: ['Over-engineering — a platform before a first model ships', 'No baseline — nothing to compare the model against', 'Silent failures — no monitoring of inputs and outputs', 'Orphaned models — nobody owns them after launch'] }, 'Watch out for common pitfalls. Some teams build an elaborate platform before shipping a single model. Others launch without a simple baseline to compare against. Many have no monitoring, so failures are silent. And models are often orphaned after launch, with nobody responsible for keeping them healthy.'),
      S('abtest', 'Measuring real impact', {}, 'Finally, remember that offline metrics are only a proxy. The real test is impact on users, measured online, for example with an A B test comparing the current and new models on live traffic. Later in this track we cover how to run such tests correctly.'),
      S('bullets', 'Recap', { style: 'recap', items: ['MLOps = DevOps + data + models', 'The ML code is a small part of the system', 'Beware training–serving skew and feedback loops', 'Maturity: manual → pipeline automation → CI/CD', 'Automate, version, test, monitor, iterate'] }, 'To recap. MLOps extends DevOps to data and models. The model code is a small part of a real system. Beware training serving skew and feedback loops. Teams mature from manual work to automated pipelines to full CI and CD. And the core habits are to automate, version, test, monitor and iterate.')
    ],
    takeaways: ['MLOps applies DevOps practices to data and models so ML systems keep working in production.', 'In real systems, the ML code is a small part; data, serving and monitoring dominate (Sculley et al., 2015).', 'Models can decay without code changes; changing anything can change everything (CACE).', 'Training–serving skew and feedback loops are common, subtle failure modes.', 'Maturity grows from manual (level 0) to automated training pipelines (level 1) to CI/CD of pipelines (level 2).', 'Version everything, test data and models, monitor predictions and outcomes, and document with model cards.'],
    quiz: [
      { q: 'What makes MLOps different from traditional DevOps?', a: ['It uses no code', 'Behaviour depends on data as well as code, and models can decay', 'It never deploys', 'It only uses GPUs'], c: 1, why: 'Data and models add new failure modes.' },
      { q: 'What is training–serving skew?', a: ['Training on a GPU and serving on a CPU', 'Features computed differently in training and in production', 'A skewed class distribution', 'A slow server'], c: 1, why: 'The model sees inputs it was not trained on.' },
      { q: 'At maturity level 1, what is automated?', a: ['Nothing', 'The training pipeline (continuous training)', 'Only the website', 'Only documentation'], c: 1, why: 'Level 2 additionally automates CI/CD of the pipelines.' },
      { q: 'A recommender that only shows popular items learns only about popular items. This is a…', a: ['Feedback loop', 'Syntax error', 'Learning-rate problem', 'Tokenisation issue'], c: 0, why: 'Predictions shape future training data.' },
      { q: 'Which is NOT a core MLOps principle?', a: ['Version data and models', 'Monitor predictions', 'Deploy large untested changes at once', 'Automate pipelines'], c: 2, why: 'Prefer small, reversible changes.' }
    ],
    read: ['what-is-mlops', 'ml-project-structure-clean-code', 'machine-learning-workflow']
  },
  {
    slug: 'data-and-experiment-management', title: 'Data Pipelines, Versioning and Experiment Tracking', track: 'mlops', level: 'Intermediate', deep: true,
    summary: 'Treat data like code: validation, versioning with DVC, leakage-safe splits, feature stores and point-in-time correctness, experiment tracking with MLflow, reproducibility and model registries.',
    scenes: [
      S('title', 'Introduction', { title: 'Data and Experiment Management', sub: 'Treat data and experiments like code', track: 'MLOps & Engineering' }, 'In machine learning, data is as important as code, often more so. Yet data is frequently copied around by hand, and experiments are remembered rather than recorded. This deep dive covers how to build reliable data pipelines, version datasets, avoid leakage, and track experiments so results can be trusted and reproduced.'),
      S('definition', 'Data-centric AI', { term: 'Data-centric AI', def: 'Improve results by systematically improving the data — labels, coverage, consistency — rather than only changing the model.', eg: 'fixing 5% of mislabelled examples can beat a bigger model' }, 'Data centric AI is the idea that systematically improving the data, its labels, coverage and consistency, often beats endlessly tweaking the model. Fixing a few percent of mislabelled examples, or collecting examples of rare cases, can improve results more than switching to a bigger architecture.'),
      S('pipeline', 'A data pipeline', { head: 'A production data pipeline', steps: ['Ingest', 'Validate', 'Clean & transform', 'Split', 'Store & version'], desc: ['Pull from databases, event streams, files and APIs.', 'Check schemas, types, ranges and freshness before anything else.', 'Handle missing values, deduplicate, compute features.', 'Create leakage-safe train, validation and test sets.', 'Save immutable, versioned snapshots with metadata.'] }, 'A production data pipeline has clear stages. Ingest data from databases, event streams and files. Validate it before anything else. Clean it and compute features. Split it into training, validation and test sets without leakage. Finally store immutable, versioned snapshots, so every model can point to exactly the data it used.'),
      S('definition', 'Data validation', { term: 'Data validation', def: 'Automated checks that data matches expectations: schema, types, allowed values, ranges, missing-value rates, uniqueness and freshness.', eg: 'tools: Great Expectations, TensorFlow Data Validation, pandera' }, 'Data validation is automated testing for data. Before training, and before serving, check the schema, types, allowed values, ranges, missing value rates, uniqueness and freshness. Tools like Great Expectations and TensorFlow Data Validation make these checks easy to write and run in every pipeline.'),
      S('question', 'Pause and think', { q: 'An upstream system silently switches a “distance” column from kilometres to miles. How could your pipeline catch it?', a: 'Range and distribution checks: values shrink by about 38%, so the mean and quantiles shift sharply. A drift or distribution test against the previous batch would fire an alert before training or serving.' }, 'Pause and think. An upstream system silently switches a distance column from kilometres to miles. How could your pipeline notice? Values suddenly shrink by about thirty eight percent, so range checks and distribution comparisons with the previous batch would fire, before the bad data reaches training or serving.'),
      S('code', 'Validation in code', { head: 'Declaring data expectations with pandera', file: 'validate.py', lines: ['import pandera as pa', '', 'schema = pa.DataFrameSchema({', '    "age": pa.Column(int, pa.Check.in_range(18, 110)),', '    "income": pa.Column(float, pa.Check.ge(0), nullable=True),', '    "country": pa.Column(str, pa.Check.isin(["BD", "FR", "IN"])),', '})', '', 'schema.validate(df)   # raises an error listing every violation'], hl: [[2, 6], 8], notes: ['Expectations for each column: type, range, allowed values, nulls', 'Run the check in the pipeline; stop on violations'] }, 'Expectations can be written as code. With the pandera library, declare each column’s type, allowed range, permitted values and whether missing values are allowed. Validating a batch raises an error that lists every violation, so the pipeline can stop before bad data reaches training or serving.'),
      S('definition', 'Data contracts', { term: 'Data contracts', def: 'An agreed, versioned specification between the team producing data and the teams consuming it: schema, meaning, freshness and change process.', eg: 'no silent renames — breaking changes require a new version and notice' }, 'Many data problems are really communication problems. A data contract is an agreed, versioned specification between the team that produces a dataset and the teams that consume it: its schema, the meaning of each field, freshness guarantees and how changes are announced. No more silent renames.'),
      S('definition', 'Data versioning', { term: 'Data versioning', def: 'Record exactly which snapshot of data each experiment and model used, so results can be reproduced and compared.', eg: 'DVC stores large files in cloud storage and small pointer files in Git' }, 'Code lives in Git, but large datasets do not fit there. Data versioning tools such as DVC store the actual files in cloud storage, and commit small pointer files to Git. Every commit then pins an exact version of both the code and the data, and anyone can check out and reproduce it.'),
      S('code', 'Versioning with DVC', { head: 'Versioning a dataset with DVC', file: 'terminal', lines: ['git init && dvc init', 'dvc remote add -d store s3://my-bucket/dvc', '', 'dvc add data/train.csv            # hash + track the file', 'git add data/train.csv.dvc .gitignore', 'git commit -m "Training data v1"', 'dvc push                           # upload data to the remote', '', 'git checkout v1 && dvc pull        # later: restore exactly v1'], hl: [[0, 1], [3, 5], 6, 8], notes: ['Set up Git, DVC and a remote store for the data', 'DVC hashes the file; Git commits the small pointer', 'Upload the actual data to cloud storage', 'Any past version can be restored exactly'] }, 'Here is the workflow. Initialise Git and DVC and configure remote storage. Adding a dataset makes DVC hash it and create a small pointer file, which you commit to Git. Push uploads the data itself. Later, checking out an old commit and pulling restores exactly the data that version used.'),
      S('lineage', 'Lineage', {}, 'With code and data both versioned, lineage connects them. Each experiment run links to a code commit and a data version, and each registered model links to its run. When a model misbehaves, you can trace back to exactly what produced it, and reproduce or fix it with confidence.'),
      S('definition', 'Data leakage', { term: 'Data leakage', def: 'Information from outside the training set — often from the future or from the test set — sneaks into training, making evaluation look better than reality.', eg: 'scaling features using statistics of the full dataset, or a feature recorded after the outcome' }, 'The most dangerous data bug is leakage: information that would not be available at prediction time sneaks into training. Examples include normalising with statistics from the full dataset, including the test set, or using a feature recorded after the outcome. Leakage makes evaluation look wonderful and production disappointing.'),
      S('split-folds', 'Leakage-safe splits', {}, 'Correct splitting is the first defence. Hold out a test set that is never touched during development, and use validation data, or k fold cross validation, for choosing models. Fit every preprocessing step on training data only, then apply it to validation and test data.'),
      S('question', 'Pause and think', { q: 'You predict next week’s sales and split your time-series data randomly into train and test. What is wrong?', a: 'Random splits let the model train on the future and test on the past — leakage. Use time-based splits: train on earlier periods, validate and test on later ones.' }, 'Pause and think. You are predicting next week’s sales, and you split your time series randomly into training and test sets. What is wrong? The model trains on days after some of its test days, effectively peeking into the future. Use time based splits: train on the past, test on later periods.'),
      S('definition', 'Stratified and group splits', { term: 'Stratified and group splits', def: 'Stratify to keep class proportions equal across splits; group-split so all records of one entity (user, patient, device) land in the same split.', eg: 'GroupKFold in scikit-learn' }, 'Two more splitting rules matter. Stratify splits so that rare classes appear in the same proportion everywhere. And split by group, so that all records belonging to one user, patient or device land in the same split. Otherwise the model can memorise individuals and look better than it really is.'),
      S('question', 'Pause and think', { q: 'A medical dataset has several scans per patient. You split scans randomly. What goes wrong?', a: 'Scans of the same patient appear in both train and test, so the model can recognise patients rather than disease — test accuracy is inflated. Split by patient.' }, 'Pause and think. A medical dataset contains several scans per patient, and you split the scans randomly. What goes wrong? Scans of the same patient end up in both training and test sets, so the model can recognise the patient instead of the disease, inflating test accuracy. Split by patient.'),
      S('definition', 'Labels', { term: 'Label quality', def: 'Clear labelling guidelines, multiple annotators on a sample, agreement metrics (e.g. Cohen’s κ), and review of disagreements.', eg: 'low agreement often means the task definition is unclear, not that annotators are careless' }, 'Labels deserve the same care. Write clear labelling guidelines, have several annotators label a sample, measure their agreement, and review disagreements. Low agreement usually signals an unclear task definition rather than careless people, and fixing the definition improves both the data and the model.'),
      S('flow', 'Feature stores', { head: 'A feature store', groups: [['OFFLINE', 80, 170, 520, 400, 'violet'], ['ONLINE', 680, 170, 520, 400, 'green']], nodes: [['raw', 'Raw data', 200, 260, 'cyan', 'events, tables'], ['fe', 'Feature pipeline', 460, 260, 'violet', 'one definition'], ['off', 'Offline store', 340, 460, 'violet', 'history for training'], ['on', 'Online store', 820, 260, 'green', 'latest values'], ['srv', 'Model server', 1060, 460, 'amber', 'real-time predictions']], edges: [['raw', 'fe'], ['fe', 'off', 'batch'], ['fe', 'on', 'sync'], ['on', 'srv', '< 10 ms']], steps: ['Raw events and tables arrive', 'Features are computed once and stored with their full history', 'The latest values are synced to a fast online store', 'The model server reads fresh features in milliseconds'] }, 'A feature store attacks training serving skew directly. Features are defined once and computed by one pipeline. Their full history goes to an offline store for training, and their latest values are synced to a fast online store. The model server reads the same features, in milliseconds, that the model was trained on.'),
      S('definition', 'Point-in-time correctness', { term: 'Point-in-time correctness', def: 'When building training data, use only feature values that were known at the moment of each historical prediction — never later updates.', eg: 'a customer’s “number of complaints” must be counted as of the prediction date' }, 'Feature stores also enforce point in time correctness. When building a training example for a past date, each feature must use only values known at that moment. Counting a customer’s complaints including those filed after the prediction date is a subtle, and very common, form of leakage.'),
      S('definition', 'Experiment tracking', { term: 'Experiment tracking', def: 'Automatically record every run’s parameters, metrics, code version, data version, environment and artefacts in a searchable store.', eg: 'MLflow, Weights & Biases, Neptune' }, 'Experiment tracking replaces memory and spreadsheets. Every training run automatically records its parameters, metrics, code and data versions, environment and output files in a searchable store. Months later you can answer: which settings produced our best model, and on which data?'),
      S('tracking', 'Comparing runs', {}, 'Here five runs are tracked. Run one, with a high learning rate, peaks early and then overfits. Run three, with a tiny learning rate, learns slowly. Run four, with dropout, reaches the best validation accuracy. With every run recorded, choosing and reproducing the winner is straightforward.'),
      S('code', 'Tracking with MLflow', { head: 'Tracking a run with MLflow', file: 'train.py', lines: ['import mlflow', '', 'mlflow.set_experiment("churn-model")', 'with mlflow.start_run():', '    params = {"lr": 0.01, "batch_size": 32, "dropout": 0.2}', '    mlflow.log_params(params)', '    model = train(**params)', '    mlflow.log_metric("val_auc", evaluate(model))', '    mlflow.set_tag("data_version", "v12")', '    mlflow.sklearn.log_model(model, "model")'], hl: [[2, 3], [4, 5], [7, 8], 9], notes: ['Group runs under an experiment and start a run', 'Log the hyperparameters', 'Log metrics and which data version was used', 'Save the model itself as an artefact of the run'] }, 'With MLflow this takes a few lines. Name an experiment and start a run. Log the hyperparameters, train, and log the validation metric. Tag the run with the data version, and save the model itself as an artefact, ready to be registered and deployed.'),
      S('table', 'What to log', { head: 'What every run should record', cols: ['Item', 'Why it matters'], widths: [1, 2.2], rows: [['Parameters & config', 'know what was tried'], ['Metrics (train, validation)', 'compare runs; spot overfitting'], ['Code version (Git commit)', 'rebuild the exact code'], ['Data version', 'rebuild the exact dataset'], ['Environment (libraries, hardware)', 'avoid “works on my machine”'], ['Artefacts (model, plots)', 'deploy or inspect later']] }, 'Every run should record its parameters and configuration, its metrics, the Git commit of the code, the data version, the software environment and hardware, and its artefacts such as the model file and diagnostic plots. Together these make any result explainable and repeatable.'),
      S('definition', 'Hyperparameter search', { term: 'Hyperparameter search', def: 'Grid search tries every combination; random search samples them; Bayesian optimisation models which settings look promising.', eg: 'random search often beats grid search when only a few hyperparameters really matter' }, 'Tracking pays off during hyperparameter search. Grid search tries every combination and wastes effort on unimportant settings. Random search samples combinations and often finds good settings faster, because usually only a few hyperparameters really matter. Bayesian optimisation learns which regions look promising.'),
      S('definition', 'Reproducibility', { term: 'Reproducibility checklist', def: 'Fix random seeds, pin library versions, containerise the environment, version data, log configuration, and note non-deterministic GPU operations.', eg: 'aim for “re-run gives the same metrics within noise”' }, 'Reproducibility needs several habits: fix random seeds, pin library versions, run inside a container, version the data, log the configuration, and be aware that some GPU operations are not deterministic. The goal is that re running a pipeline gives the same metrics, within a small amount of noise.'),
      S('question', 'Pause and think', { q: 'You re-run last month’s training script and get 2% lower accuracy. List three likely causes.', a: 'Different data (the source changed), different library versions, and uncontrolled randomness (seeds, data order, non-deterministic GPU kernels).' }, 'Pause and think. You re run last month’s training script and get two percent lower accuracy. What could explain it? The underlying data may have changed, library versions may differ, or randomness from seeds, data order or non deterministic GPU kernels was not controlled. Versioning and pinning would tell you which.'),
      S('definition', 'Model registry', { term: 'Model registry', def: 'A catalogue of trained models with versions, metadata and lifecycle stages such as staging, production and archived.', eg: 'deployments reference “churn-model, version 7”, never a loose file' }, 'A model registry is the catalogue of trained models. Each version carries its metadata, lineage and a lifecycle stage, such as staging, production or archived. Deployments reference a named, versioned model rather than a loose file on someone’s laptop, which makes promotions and rollbacks clean.'),
      S('flow', 'Promotion flow', { head: 'From experiment to production', nodes: [['run', 'Tracked run', 180, 330, 'cyan'], ['reg', 'Registry v7', 470, 330, 'violet', 'stage: staging'], ['rev', 'Review & checks', 780, 330, 'amber', 'tests, fairness, sign-off'], ['prod', 'Production', 1080, 330, 'lime', 'stage: production'], ['arc', 'v6 archived', 1080, 520, 'muted', 'kept for rollback']], edges: [['run', 'reg', 'register'], ['reg', 'rev'], ['rev', 'prod', 'promote'], ['prod', 'arc', 'replace']], steps: ['The best run is registered as a new version', 'It starts in staging', 'Automated checks and a human review decide', 'It is promoted to production', 'The previous version is archived but kept for rollback'] }, 'The flow is simple. The best tracked run is registered as a new version in staging. Automated tests, fairness checks and a human review decide whether it is promoted to production. The previous version is archived, but kept ready, so a rollback takes seconds.'),
      S('definition', 'Datasheets', { term: 'Datasheets for datasets', def: 'Document why a dataset was created, what it contains, how it was collected and labelled, known gaps and biases, and allowed uses.', eg: 'proposed by Gebru et al. (2018), inspired by electronics datasheets' }, 'Datasets deserve documentation too. Datasheets for datasets, proposed in 2018, record why a dataset was created, what it contains, how it was collected and labelled, its known gaps and biases, and how it may be used. They prevent a dataset from being misused long after its creators have moved on.'),
      S('bullets', 'Privacy and governance', { head: 'Data governance essentials', items: ['Minimise — collect only what the model needs', 'Protect — mask or remove personal data (PII)', 'Consent & licensing — know your rights to use data', 'Retention — delete data when it is no longer needed'] }, 'Data governance is not optional. Collect only what the model needs. Mask or remove personal information. Make sure you have consent and the licences to use the data. And delete data once it is no longer needed. Regulations such as the GDPR make these obligations legal requirements in many countries.'),
      S('question', 'Pause and think', { q: 'Two teams compute “customer tenure” slightly differently — one in days, one in months, rounded. What is the long-term fix?', a: 'A single shared, versioned feature definition (a feature store or shared feature library) used by both training and serving, and by every team.' }, 'Pause and think. Two teams compute customer tenure differently, one in days and one in rounded months. What is the lasting fix? One shared, versioned feature definition, in a feature store or shared library, used by training, by serving and by every team.'),
      S('bullets', 'Best practices', { head: 'Best practices', items: ['Validate data at every boundary', 'Version datasets and link them to runs', 'Split by time or group to avoid leakage', 'Track every experiment automatically', 'Register models; never deploy loose files'] }, 'In short: validate data at every boundary, version datasets and link them to runs, split by time or group to avoid leakage, track every experiment automatically, and register models instead of deploying loose files. These habits make results trustworthy and teams faster.'),
      S('bullets', 'Recap', { style: 'recap', items: ['Data quality often beats model changes', 'Validate, version (DVC) and document data', 'Leakage: split carefully, fit preprocessing on train only', 'Feature stores: one definition, point-in-time correct', 'Track runs (MLflow) and promote via a registry'] }, 'To recap. Better data often beats a better model. Validate, version and document your data. Prevent leakage with careful splits and point in time correct features. Track every experiment, and promote models through a registry with clear stages.')
    ],
    takeaways: ['Data-centric work — fixing labels, coverage and consistency — often beats changing the model.', 'Validate data automatically (schema, ranges, missing values, freshness) at every pipeline boundary.', 'DVC versions large datasets with small pointer files in Git; lineage links data, code, runs and models.', 'Leakage makes offline results misleading; use time/group splits and fit preprocessing on training data only.', 'Feature stores share one feature definition between training and serving with point-in-time correctness.', 'Track every run (params, metrics, code and data versions, artefacts) and promote models through a registry.'],
    quiz: [
      { q: 'What does DVC commit to Git?', a: ['The full dataset', 'A small pointer file with the data’s hash', 'Only images', 'Nothing'], c: 1, why: 'The data itself lives in remote storage.' },
      { q: 'Which is an example of data leakage?', a: ['Using dropout', 'Scaling features with statistics computed on the full dataset including the test set', 'Logging metrics', 'Using a registry'], c: 1, why: 'Test information influences training.' },
      { q: 'How should you split a time-series forecasting dataset?', a: ['Randomly', 'By time: train on the past, test on later periods', 'Alphabetically', 'By file size'], c: 1, why: 'Random splits let the model see the future.' },
      { q: 'Point-in-time correctness means…', a: ['Training on the newest data only', 'Features for a past example use only values known at that time', 'Serving within 10 ms', 'Logging timestamps'], c: 1, why: 'Later updates would leak the future.' },
      { q: 'Why use a model registry?', a: ['To store raw data', 'To version models with stages and metadata for safe promotion and rollback', 'To tokenise text', 'To speed up GPUs'], c: 1, why: 'Deploy named versions, not loose files.' }
    ],
    read: ['data-versioning-and-pipelines', 'experiment-tracking', 'feature-stores', 'reproducibility-in-ml']
  },
  {
    slug: 'packaging-and-serving-models', title: 'Packaging and Serving Models', track: 'mlops', level: 'Intermediate', deep: true,
    summary: 'From a model file to a reliable service: batch vs online inference, a FastAPI endpoint, Docker images, Kubernetes and autoscaling, latency percentiles and queueing, GPU batching, optimisation and edge deployment.',
    scenes: [
      S('title', 'Introduction', { title: 'Packaging and Serving Models', sub: 'From a model file to a reliable service', track: 'MLOps & Engineering' }, 'A trained model is just a file until something uses it. Serving is the engineering that turns that file into predictions for real users, quickly, reliably and affordably. In this deep dive we package a model, put it behind an API, containerise it and scale it.'),
      S('definition', 'The model artefact', { term: 'Model artefact', def: 'Everything needed to make a prediction: learned weights, preprocessing steps, feature order, label mapping and metadata such as versions.', eg: 'save the whole pipeline (scaler + model), not just the model' }, 'The model artefact must contain everything needed to make a prediction: the learned weights, the preprocessing steps, the expected feature order, the label mapping and metadata such as library versions. A classic bug is saving the model but not the scaler that prepared its inputs.'),
      S('compare', 'Batch vs online', { head: 'Two ways to serve predictions', left: { title: 'Batch inference', items: ['Score many records on a schedule', 'Write results to a table', 'Simple, cheap, high throughput'], color: 'cyan' }, right: { title: 'Online inference', items: ['Answer each request in real time', 'An API behind a load balancer', 'Needs low latency and high availability'], color: 'lime' } }, 'There are two basic ways to serve. Batch inference scores many records on a schedule, perhaps every night, and writes results to a table. It is simple and cheap. Online inference answers each request in real time through an API, which demands low latency and high availability.'),
      S('table', 'Serving patterns', { head: 'Choosing a serving pattern', cols: ['Pattern', 'Latency', 'Example'], widths: [1, 1, 2], rows: [['Batch', 'minutes – hours', 'nightly churn scores for the marketing team'], ['Online API', '10 – 200 ms', 'fraud check during card payment'], ['Streaming', 'seconds', 'anomaly detection on sensor events'], ['On-device (edge)', '< 20 ms, offline', 'keyboard next-word suggestion on a phone']] }, 'Choose the pattern by how fresh the prediction must be. Batch suits nightly scores. Online APIs suit decisions during a user action, like a fraud check while paying. Streaming handles continuous event flows, such as sensor data. On device inference gives instant, offline predictions, like keyboard suggestions.'),
      S('question', 'Pause and think', { q: 'A marketing team wants a churn-risk score for every customer, refreshed daily, to plan emails. Which serving pattern?', a: 'Batch inference: score all customers nightly and store the results. No real-time API is needed, which keeps it simple and cheap.' }, 'Pause and think. The marketing team wants a churn risk score for every customer, refreshed daily, to plan emails. Which serving pattern fits? Batch inference. Score everyone overnight and store the results in a table. A real time API would add cost and complexity with no benefit.'),
      S('code', 'An API with FastAPI', { head: 'A prediction API with FastAPI', file: 'app.py', lines: ['from fastapi import FastAPI', 'from pydantic import BaseModel', 'import joblib', '', 'app = FastAPI()', 'model = joblib.load("model.joblib")      # load ONCE at start-up', '', 'class Features(BaseModel):              # validated input schema', '    age: float', '    income: float', '', '@app.post("/v1/predict")', 'def predict(f: Features):', '    p = model.predict_proba([[f.age, f.income]])[0, 1]', '    return {"probability": float(p), "model_version": "7"}'], hl: [5, [7, 9], [11, 14]], notes: ['Load the model once when the server starts', 'Pydantic validates every request against a schema', 'A versioned endpoint returns the prediction and the model version'] }, 'Here is an online prediction service in fifteen lines of Python with FastAPI. The model is loaded once, when the server starts. A schema validates every incoming request, rejecting malformed input. The versioned endpoint returns the probability together with the model version, which helps debugging later.'),
      S('question', 'Pause and think', { q: 'Why load the model at start-up instead of inside the predict function?', a: 'Loading from disk can take seconds and lots of memory. Doing it per request would make every prediction slow; loading once keeps requests fast.' }, 'Pause and think. Why load the model at start up rather than inside the prediction function? Loading from disk can take seconds and a lot of memory. Doing it for every request would make every prediction painfully slow. Load once, then reuse the model for thousands of requests.'),
      S('docker', 'Containers', {}, 'Next, package the service in a container. A Dockerfile builds an image layer by layer: a base image with Python, the dependency list, the installed libraries, the model and code, and the start command. The same image then runs identically on a laptop, a cloud virtual machine or a Kubernetes cluster.'),
      S('code', 'The Dockerfile', { head: 'A Dockerfile for the service', file: 'Dockerfile', lines: ['FROM python:3.11-slim', 'WORKDIR /app', 'COPY requirements.txt .', 'RUN pip install --no-cache-dir -r requirements.txt', 'COPY model.joblib app.py ./', 'EXPOSE 8000', 'CMD ["uvicorn", "app:app", "--host", "0.0.0.0", "--port", "8000"]'], hl: [0, [2, 3], 4, 6], notes: ['A small official base image', 'Install pinned dependencies first — this layer is cached', 'Copy the model and code last, since they change most often', 'Start the web server'] }, 'The Dockerfile is short. Start from a small official Python image. Copy the requirements and install them first, so that this slow layer is cached and reused. Copy the model and code last, because they change most often. Finally, expose the port and start the web server.'),
      S('definition', 'Layer caching', { term: 'Layer caching', def: 'Docker reuses unchanged layers. Order instructions from least to most frequently changed so rebuilds are fast.', eg: 'changing app.py should not trigger reinstalling every library' }, 'Order matters because Docker caches layers. If a layer and everything before it are unchanged, Docker reuses it. By installing libraries before copying the application code, a one line code change rebuilds in seconds instead of reinstalling every library.'),
      S('definition', 'Orchestration', { term: 'Kubernetes', def: 'Runs containers across a cluster: keeps the desired number of replicas alive, restarts failures, rolls out new versions and scales on demand.', eg: 'describe what you want (3 replicas of image v7); Kubernetes makes it so' }, 'At scale, containers are run by an orchestrator, most often Kubernetes. You declare what you want, such as three replicas of version seven, and Kubernetes keeps it that way: restarting crashed containers, spreading them across machines, rolling out new versions gradually and scaling up or down with demand.'),
      S('flow', 'The request path', { head: 'The path of a prediction request', nodes: [['c', 'Client', 150, 330, 'cyan'], ['lb', 'Load balancer', 430, 330, 'violet'], ['r1', 'Replica 1', 760, 230, 'lime'], ['r2', 'Replica 2', 760, 330, 'lime'], ['r3', 'Replica 3', 760, 430, 'lime'], ['as', 'Autoscaler', 1080, 330, 'amber', 'watches load']], edges: [['c', 'lb', 'HTTPS'], ['lb', 'r1'], ['lb', 'r2'], ['lb', 'r3'], ['r2', 'as', 'metrics'], ['as', 'r3', 'add / remove', -40]], steps: ['A client sends a request', 'The load balancer spreads requests…', '…across healthy replicas…', '…so none is overloaded', 'Replicas report load metrics', 'The autoscaler adds or removes replicas'] }, 'A request travels from the client to a load balancer, which spreads traffic across several identical replicas and skips unhealthy ones. The replicas report metrics such as CPU use and request rate, and an autoscaler adds replicas when load rises and removes them when it falls.'),
      S('serving', 'Autoscaling under real traffic', {}, 'Here is a simulated day of traffic. As demand rises in the morning, the autoscaler adds replicas and latency stays low. Around midday a sudden burst arrives faster than new replicas can start, and the ninety fifth percentile latency jumps above the two hundred millisecond objective before capacity catches up.'),
      S('code', 'Autoscaling config', { head: 'A Kubernetes autoscaler for the API', file: 'hpa.yaml', lines: ['apiVersion: autoscaling/v2', 'kind: HorizontalPodAutoscaler', 'metadata: { name: churn-api }', 'spec:', '  scaleTargetRef: { apiVersion: apps/v1, kind: Deployment, name: churn-api }', '  minReplicas: 2', '  maxReplicas: 10', '  metrics:', '    - type: Resource', '      resource: { name: cpu, target: { type: Utilization, averageUtilization: 60 } }'], hl: [4, [5, 6], [7, 9]], notes: ['Which deployment to scale', 'Never fewer than 2 replicas (availability), never more than 10 (cost)', 'Add replicas when average CPU use exceeds 60%'] }, 'Autoscaling is configured declaratively. This Kubernetes horizontal pod autoscaler targets the churn API deployment, keeps at least two replicas for availability and at most ten to cap cost, and adds replicas whenever average CPU use rises above sixty percent, leaving headroom for bursts.'),
      S('definition', 'Cold starts', { term: 'Cold starts', def: 'A new replica must start its container, load the model into memory (or GPU) and warm up before it can serve. For large models this can take minutes.', eg: 'keep a minimum of warm replicas; pre-load models; scale on leading indicators' }, 'Scaling is not instant. A new replica must start its container, load the model into memory, possibly onto a GPU, and warm up before serving. For large models this cold start can take minutes, which is why services keep a minimum of warm replicas and scale on early signals such as rising queue length.'),
      S('definition', 'Latency percentiles', { term: 'p50, p95, p99', def: 'The latency below which 50%, 95% or 99% of requests complete. Averages hide slow outliers; percentiles expose them.', eg: 'p50 = 40 ms but p99 = 900 ms means 1 in 100 users waits almost a second' }, 'Latency is measured with percentiles, not averages. The fiftieth percentile is the typical request. The ninety fifth and ninety ninth percentiles show the slow tail. A median of forty milliseconds can hide a ninety ninth percentile of nearly a second, which one user in a hundred experiences.'),
      S('question', 'Pause and think', { q: 'A page makes 20 independent model calls, each with a 1% chance of being slow. What fraction of page loads include at least one slow call?', a: '1 − 0.99²⁰ ≈ 18%. Tail latency compounds when requests fan out, so p99 matters far more than it seems.' }, 'Pause and think. A page makes twenty independent model calls, and each has a one percent chance of being slow. How many page loads include at least one slow call? One minus point nine nine to the twentieth power, about eighteen percent. Tail latency compounds when requests fan out.'),
      S('plot', 'Queueing', { head: 'Why latency explodes near full utilisation', x: [0, 0.97], y: [0, 30], xstep: 0.1, ystep: 5, fns: [{ f: '1 / (1 - x)', c: 'amber', label: 'relative wait time ∝ 1 / (1 − ρ)', lx: 0.72, dy: -30 }], vlines: [[0.7, 'safe operating zone', 'green']], xl: 'utilisation ρ (fraction of capacity in use)', note: 'At 50% busy, waits double; at 90%, they are 10×; at 95%, 20×.' }, 'Why does latency spike? Queueing theory gives a simple rule: in a basic queue, waiting time grows like one over one minus the utilisation. At half capacity, waits double. At ninety percent, they are ten times longer, and at ninety five percent, twenty times. So services are usually run well below full capacity.'),
      S('question', 'Pause and think', { q: 'Your service runs at 80% utilisation. Using the 1/(1 − ρ) rule, how much longer are waits than at 50%?', a: 'At 80%: 1/(1 − 0.8) = 5. At 50%: 1/(1 − 0.5) = 2. Waits are about 2.5× longer — and they grow explosively beyond this.' }, 'Pause and think. Your service runs at eighty percent utilisation. Using the one over one minus rho rule, how much longer are waits than at fifty percent? At eighty percent the factor is five, and at fifty percent it is two, so waits are about two and a half times longer, and they explode beyond this point.'),
      S('stats', 'Latency budgets', { head: 'How fast is fast enough? (human response-time limits)', items: [['0.1 s', 'feels instant', 'e.g. autocomplete'], ['1 s', 'keeps the flow of thought', 'e.g. search results'], ['10 s', 'limit of attention', 'show progress or stream results']] }, 'How fast must a model be? Classic usability research gives three limits. About a tenth of a second feels instant. About one second keeps the user’s flow of thought. Around ten seconds is the limit of attention, beyond which you must show progress, or stream results as chatbots do.'),
      S('definition', 'GPU serving', { term: 'Dynamic batching', def: 'GPU servers (e.g. NVIDIA Triton) briefly queue incoming requests and run them together as one batch, trading a few milliseconds of latency for much higher throughput.', eg: 'wait up to 5 ms to fill a batch of 16' }, 'Deep learning models are often served on GPUs, which are efficient only with batches. Servers such as NVIDIA Triton use dynamic batching: they hold incoming requests for a few milliseconds, group them, and run them together. A small latency cost buys a large gain in throughput and cost per prediction.'),
      S('definition', 'Optimising the model', { term: 'Serving optimisations', def: 'Export to an optimised runtime (ONNX Runtime, TensorRT), quantise to INT8, prune, or distil into a smaller model.', eg: 'often 2–10× cheaper serving for a small accuracy cost' }, 'The model itself can be optimised for serving. Export it to an optimised runtime such as ONNX Runtime or TensorRT, quantise weights to eight bit integers, prune unnecessary connections, or distil it into a smaller student model. These steps can make serving several times cheaper for a small accuracy cost.'),
      S('quantize', 'Quantisation', {}, 'Quantisation is often the easiest win. Storing weights in eight bit integers instead of thirty two bit floats cuts memory by four and speeds up inference on hardware with integer support. Calibration on sample data keeps the accuracy loss small, so always measure before and after.'),
      S('definition', 'CPU or GPU?', { term: 'Choosing hardware', def: 'Small tabular and tree models: CPUs are cheap and fast enough. Large neural networks and high throughput: GPUs or other accelerators.', eg: 'a gradient-boosted tree answers in under a millisecond on a CPU' }, 'Not every model needs a GPU. Gradient boosted trees and small networks answer in well under a millisecond on ordinary CPUs, which are cheaper and simpler to operate. GPUs and other accelerators pay off for large neural networks and high throughput workloads.'),
      S('definition', 'Edge deployment', { term: 'On-device (edge) inference', def: 'Convert models to mobile formats (TensorFlow Lite, Core ML, ONNX Runtime Mobile) and run them on the device.', eg: 'no network round-trip, works offline, data stays private' }, 'Some models run on the device itself, converted to formats such as TensorFlow Lite, Core ML or ONNX Runtime Mobile. Edge inference removes the network round trip, works offline and keeps personal data on the device. The trade off is tight limits on memory, power and model size.'),
      S('definition', 'Caching', { term: 'Prediction caching', def: 'If the same inputs recur, store and reuse predictions. Also precompute predictions for common cases.', eg: 'cache recommendations per user for 10 minutes instead of recomputing on every page view' }, 'Sometimes the fastest prediction is the one you do not compute. If the same inputs recur, cache the results for a while. Recommendations for a user can be cached for a few minutes, and predictions for common cases can be precomputed in batch and simply looked up.'),
      S('definition', 'Load testing', { term: 'Load testing', def: 'Before launch, simulate realistic and peak traffic (e.g. with Locust or k6) to measure throughput, tail latency and the breaking point.', eg: 'test at 2–3× the expected peak and watch p99, errors and memory' }, 'Before launch, load test. Tools such as Locust or k6 simulate realistic and peak traffic against the service, measuring throughput, tail latency and where it breaks. Test at two or three times the expected peak, and watch the ninety ninth percentile latency, error rates and memory, not just averages.'),
      S('definition', 'Serving many models', { term: 'Multi-model serving', def: 'One server hosts many models or versions, loading them on demand; requests name the model and version they want.', eg: 'per-country models, or v6 and v7 side by side during a migration' }, 'Real systems often serve many models: one per country, per customer segment, or two versions side by side during a migration. Multi model servers host many models, load them on demand and route each request by name and version, sharing hardware efficiently.'),
      S('bullets', 'API design', { head: 'Designing a model API', items: ['Version endpoints — /v1/predict, /v2/predict', 'Validate inputs — strict schemas, clear errors', 'Return metadata — model version, confidence', 'Set timeouts — and a fallback answer'] }, 'Design the API carefully. Version the endpoints, so clients can migrate gradually. Validate inputs with strict schemas and clear error messages. Return metadata such as the model version and confidence. And set timeouts, with a sensible fallback answer when the model is slow or unavailable.'),
      S('bullets', 'Reliability', { head: 'Keeping the service reliable', items: ['Health checks — readiness and liveness endpoints', 'Graceful degradation — simple rules if the model fails', 'Rate limiting — protect against overload and abuse', 'Security — authentication and encrypted traffic'] }, 'Reliability comes from a few habits. Health check endpoints let the orchestrator know when a replica is ready or stuck. Graceful degradation falls back to simple rules if the model fails. Rate limiting protects against overload and abuse, and authentication and encrypted traffic keep the service secure.'),
      S('question', 'Pause and think', { q: 'Your fraud model’s server goes down during a sale. What should the payment system do?', a: 'Fail gracefully: apply a simple fallback (rules or a cached/cheaper model) with conservative thresholds, log the event, and alert on-call — never block all payments or approve everything blindly.' }, 'Pause and think. The fraud model’s server goes down during a big sale. What should the payment system do? Fail gracefully: switch to a simple rule based fallback with conservative thresholds, log the event and alert the on call engineer. Blocking every payment, or approving everything blindly, would both be disasters.'),
      S('bullets', 'Recap', { style: 'recap', items: ['Package the whole pipeline, not just the weights', 'Pick batch, online, streaming or edge by freshness needs', 'FastAPI + Docker + Kubernetes is a common stack', 'Watch p95/p99 latency; keep utilisation well below 100%', 'Optimise: batching, quantisation, caching, right hardware'] }, 'To recap. Package the whole prediction pipeline. Choose batch, online, streaming or edge serving by how fresh predictions must be. A common stack is FastAPI, Docker and Kubernetes. Watch tail latency and keep utilisation well below capacity, and optimise with batching, quantisation, caching and the right hardware.')
    ],
    takeaways: ['A model artefact must include preprocessing, feature order and metadata — not just weights.', 'Choose batch, online, streaming or edge serving based on how fresh predictions must be.', 'A typical stack: FastAPI (schema-validated API) → Docker image → Kubernetes replicas with autoscaling.', 'Measure latency percentiles (p95/p99); tail latency compounds when requests fan out.', 'Queueing: waits grow like 1/(1 − ρ), so run well below full utilisation.', 'Dynamic batching, quantisation, optimised runtimes, caching and the right hardware cut serving cost.'],
    quiz: [
      { q: 'Which serving pattern suits nightly scores for every customer?', a: ['Online API', 'Batch inference', 'Edge inference', 'Streaming'], c: 1, why: 'No real-time need; batch is simple and cheap.' },
      { q: 'Why copy application code AFTER installing dependencies in a Dockerfile?', a: ['It is required by Docker', 'So code changes do not invalidate the cached dependency layer', 'To make the image larger', 'To avoid using Python'], c: 1, why: 'Layer caching speeds up rebuilds.' },
      { q: 'What does p99 latency tell you?', a: ['The average latency', 'The latency that 99% of requests are faster than', 'The number of replicas', 'CPU usage'], c: 1, why: 'It exposes the slow tail.' },
      { q: 'In a simple queue, what happens to waiting time as utilisation approaches 100%?', a: ['It drops', 'It stays constant', 'It grows sharply, like 1/(1 − ρ)', 'It becomes zero'], c: 2, why: 'Leave headroom.' },
      { q: 'What is dynamic batching on a GPU server?', a: ['Training in batches', 'Briefly grouping incoming requests to run them together for higher throughput', 'Splitting a model across GPUs', 'Caching predictions'], c: 1, why: 'Trade a little latency for throughput.' }
    ],
    read: ['model-serving-and-apis', 'docker-for-machine-learning', 'gpus-and-ml-hardware', 'edge-ai-tinyml']
  },
  {
    slug: 'ci-cd-and-deployment-strategies', title: 'CI/CD for ML and Safe Deployment Strategies', track: 'mlops', level: 'Intermediate', deep: true,
    summary: 'Automate the path to production: testing code, data and models; CI/CD/CT pipelines with quality gates; champion–challenger evaluation; shadow, canary and blue–green deployments; and fast rollback.',
    scenes: [
      S('title', 'Introduction', { title: 'CI/CD for Machine Learning', sub: 'Testing, quality gates and safe releases', track: 'MLOps & Engineering' }, 'How do you change a model that millions of people rely on without breaking anything? You automate the path to production and release changes gradually, with the ability to undo them instantly. This deep dive covers continuous integration, delivery and training for machine learning, and the deployment strategies that keep releases safe.'),
      S('definition', 'CI, CD and CT', { term: 'CI · CD · CT', def: 'Continuous Integration: test every change automatically. Continuous Delivery/Deployment: release automatically and safely. Continuous Training: retrain automatically on new data.', eg: 'CT is the ML-specific addition' }, 'Three ideas work together. Continuous integration tests every change automatically. Continuous delivery, or deployment, releases changes automatically and safely. Machine learning adds continuous training, which retrains models automatically when new data arrives, because a model can go stale even when the code does not change.'),
      S('ci', 'A CI/CD pipeline', {}, 'Here is a pipeline in action. A commit triggers unit tests and a data schema check. The model is trained on the latest data, then evaluated: accuracy must reach at least point nine and there must be no fairness regression. The model is registered, and finally deployed as a canary to five percent of traffic.'),
      S('table', 'Tests for ML', { head: 'What to test in an ML system', cols: ['Test type', 'Checks', 'Example'], widths: [1, 1.5, 2], rows: [['Unit tests', 'code logic', 'feature function handles missing values'], ['Data tests', 'schema, ranges, freshness', 'no negative ages; data less than 24 h old'], ['Model quality', 'metrics vs thresholds', 'AUC ≥ 0.85 overall and per segment'], ['Behavioural tests', 'expected model behaviour', 'swapping a name does not change sentiment'], ['Integration tests', 'end-to-end service', 'API returns a valid response in < 200 ms']] }, 'Machine learning needs several kinds of tests. Unit tests check code logic. Data tests check schemas, ranges and freshness. Model quality tests compare metrics with thresholds, overall and for important segments. Behavioural tests check expected behaviours, and integration tests check the whole service end to end.'),
      S('definition', 'Behavioural testing', { term: 'Behavioural tests (after CheckList)', def: 'Test capabilities like software: invariance (irrelevant changes should not change the output), directional expectations (some changes should move it one way), and minimum functionality.', eg: '“The service was great” → positive; adding “not” should flip it' }, 'Behavioural testing, popularised by the CheckList method, treats a model like software with specifications. Invariance tests check that irrelevant changes, such as swapping a person’s name, do not change the output. Directional tests check that some changes move the output the expected way, like adding the word not.'),
      S('question', 'Pause and think', { q: 'Write one invariance test for a loan-approval model.', a: 'Changing only the applicant’s name (or another protected attribute that should be irrelevant) while keeping every financial feature identical must not change the decision.' }, 'Pause and think. Can you write an invariance test for a loan approval model? For example: change only the applicant’s name, or another attribute that should be irrelevant, while keeping every financial detail identical. The decision must not change. Failures reveal bias or brittle behaviour.'),
      S('ci', 'A failing quality gate', { fail: 3, failMsg: 'accuracy 0.87 < 0.90 ✗ — deployment blocked' }, 'Now watch a quality gate do its job. Tests pass and training completes, but the new model scores only point eight seven, below the required point nine. The pipeline stops, the model is never registered or deployed, and the team is notified. Bad models are caught automatically, before users ever see them.'),
      S('definition', 'Quality gates', { term: 'Quality gate', def: 'An automated check that must pass before the pipeline continues: minimum metrics, no regression versus production, fairness and latency budgets.', eg: 'block if the new model is worse than the current one on any key segment' }, 'A quality gate is an automated checkpoint the pipeline must pass. Typical gates require minimum metrics, no regression compared with the model in production, fairness checks across groups, and latency within budget. Gates turn quality standards from good intentions into enforced rules.'),
      S('code', 'A CI workflow', { head: 'A CI workflow with GitHub Actions', file: '.github/workflows/ml-ci.yml', lines: ['name: ml-ci', 'on: [push]', 'jobs:', '  test-train-evaluate:', '    runs-on: ubuntu-latest', '    steps:', '      - uses: actions/checkout@v4', '      - uses: actions/setup-python@v5', '        with: { python-version: "3.11" }', '      - run: pip install -r requirements.txt', '      - run: pytest tests/', '      - run: python train.py --config configs/prod.yaml', '      - run: python evaluate.py --min-accuracy 0.90'], hl: [[0, 1], [6, 9], 10, [11, 12]], notes: ['Run on every push', 'Check out code and set up a pinned environment', 'Unit and data tests', 'Train, then fail the build if accuracy is below the gate'] }, 'Here is a small CI workflow for GitHub Actions. On every push it checks out the code, sets up a pinned Python environment and installs dependencies. It runs the unit and data tests, trains the model with a versioned configuration, and runs an evaluation script that fails the build if accuracy is below the gate.'),
      S('definition', 'Continuous training', { term: 'Continuous training triggers', def: 'Retrain on a schedule (e.g. weekly), when enough new labelled data arrives, or when monitoring detects drift or performance decay.', eg: 'automated retraining still passes through the same gates' }, 'Continuous training needs triggers. Some teams retrain on a schedule, such as weekly. Others retrain when enough new labelled data has accumulated, or when monitoring detects drift or falling performance. Either way, an automatically retrained model must pass through exactly the same tests and gates.'),
      S('flow', 'A CT pipeline', { head: 'A continuous-training pipeline', nodes: [['t', 'Trigger', 150, 330, 'amber', 'schedule or drift'], ['v', 'Validate data', 400, 330, 'cyan'], ['tr', 'Train', 640, 330, 'violet'], ['e', 'Evaluate vs champion', 900, 330, 'lime', 'same test set'], ['r', 'Register', 1120, 230, 'green'], ['x', 'Stop & alert', 1120, 440, 'red']], edges: [['t', 'v'], ['v', 'tr'], ['tr', 'e'], ['e', 'r', 'better'], ['e', 'x', 'worse']], steps: ['A schedule or a drift alert triggers the pipeline', 'New data is validated first', 'A challenger model is trained', 'It is compared with the current champion on the same data', 'If better, it is registered for deployment…', '…otherwise the pipeline stops and alerts the team'] }, 'A continuous training pipeline starts from a trigger, validates the new data, trains a challenger model and compares it with the current champion on the same evaluation data. If the challenger is better, it is registered for deployment. If not, the pipeline stops and alerts the team, and the champion stays in place.'),
      S('definition', 'Champion vs challenger', { term: 'Champion–challenger', def: 'The production model (champion) is replaced only when a new model (challenger) beats it on agreed metrics — first offline, then on live traffic.', eg: 'keeps quality from silently sliding backwards' }, 'This champion challenger pattern keeps quality from sliding backwards. The model in production, the champion, is only replaced when a challenger beats it on agreed metrics: first offline on held out data, and then online, on a small share of real traffic.'),
      S('question', 'Pause and think', { q: 'The challenger is 0.5% better than the champion offline. Should you switch 100% of traffic to it immediately?', a: 'No. Offline gains may not hold online, and new failure modes may appear. Roll out gradually (shadow, then canary or an A/B test) while monitoring, with rollback ready.' }, 'Pause and think. The challenger is half a percent better offline. Should you switch all traffic to it immediately? No. Offline gains do not always hold on live traffic, and new failure modes can appear. Roll it out gradually while monitoring, with a rollback ready.'),
      S('definition', 'Shadow deployment', { term: 'Shadow deployment', def: 'Send a copy of live traffic to the new model, but only the old model’s answers are used. Compare outputs, latency and errors with zero user risk.', eg: 'great for catching crashes and skew before any user is affected' }, 'The safest first step is shadow deployment. A copy of live requests goes to the new model, but users only ever see the old model’s answers. You can compare predictions, latency and errors on real traffic with zero risk to users, catching crashes and training serving skew early.'),
      S('question', 'Pause and think', { q: 'A shadow deployment shows the new model’s predictions look sensible. What can it NOT tell you?', a: 'The effect on users and business outcomes — nobody ever acted on the new model’s outputs. You still need a canary or A/B test for that.' }, 'Pause and think. A shadow deployment shows the new model’s predictions look sensible and fast. What can it not tell you? How users and business outcomes respond, because nobody ever acted on its outputs. You still need a canary release or an A B test to learn that.'),
      S('rollout', 'Canary release', {}, 'Next comes a canary release. The new version receives one percent of traffic, then five, then twenty five, fifty and finally one hundred percent. At each step, error rates and business metrics are checked against the old version. A bad release reaches only a few users before it is caught.'),
      S('rollout', 'Automatic rollback', { mode: 'rollback' }, 'Here the canary goes wrong. At twenty five percent of traffic, the new version’s error rate climbs past the two percent threshold. The rollout is stopped automatically and all traffic returns to the old version. Only a quarter of users saw the bad version, and only briefly.'),
      S('definition', 'Blue–green deployment', { term: 'Blue–green deployment', def: 'Run two full environments: blue (current) and green (new). Test green, then switch all traffic at once — and switch back instantly if needed.', eg: 'simple, fast rollback; costs double capacity during the switch' }, 'Blue green deployment runs two complete environments. Blue serves users while green, with the new version, is tested. Then all traffic switches to green at once. If anything goes wrong, traffic switches straight back to blue. It gives instant rollback, at the cost of running double capacity during the switch.'),
      S('compare', 'Canary vs blue–green', { head: 'Choosing a release strategy', left: { title: 'Canary', items: ['Gradual: 1% → 100%', 'Real feedback from a few users', 'Slower, needs good monitoring'], color: 'lime' }, right: { title: 'Blue–green', items: ['All-at-once switch', 'Instant, whole-system rollback', 'Every user is exposed immediately'], color: 'blue' } }, 'Canary releases are gradual and expose only a few users at first, but they take longer and depend on good monitoring. Blue green switches everyone at once with instant rollback, but every user is exposed immediately. Many teams shadow first, then canary, keeping the previous version warm for a blue green style rollback.'),
      S('definition', 'Feature flags', { term: 'Feature flags', def: 'Configuration switches that turn a model or behaviour on or off, or route specific users to it, without redeploying.', eg: 'enable the new ranking model for employees first, then 5% of users' }, 'Feature flags add fine control without redeploying. A configuration switch can turn a new model on or off, or route specific groups, such as employees or one country, to it. Flags make it easy to test with friendly users first, and to turn a problem off in seconds.'),
      S('abtest', 'Online evaluation', {}, 'To decide whether the new model is truly better, many teams run an A B test during the rollout, comparing a business metric such as conversion between the two versions. Here the new model’s advantage becomes statistically clear by the planned end of the test, and it is rolled out.'),
      S('pipeline', 'Build once, deploy many', { head: 'Promote one artefact through environments', steps: ['Build image v7', 'Dev', 'Staging', 'Production'], desc: ['Build and test the container image once, tag it immutably.', 'Deploy the SAME image with development configuration.', 'Deploy the SAME image against production-like data and load.', 'Deploy the SAME image to users — only configuration differs.'] }, 'A key rule is build once, deploy many. Build and test one immutable image, then promote that exact image through development, staging and production, changing only configuration. What you tested is exactly what you ship, so there are no surprises caused by rebuilding.'),
      S('definition', 'Rollback readiness', { term: 'Fast rollback', def: 'Keep the previous model version deployed or instantly deployable, with its features and configuration. Practise rollbacks.', eg: 'target: back to the old model in minutes, not days' }, 'Always be ready to roll back. Keep the previous model version deployed or instantly deployable, together with the feature pipeline and configuration it expects. Practise rollbacks regularly. The goal is to be back on the old model within minutes, not days, whenever something looks wrong.'),
      S('definition', 'Slice-based validation', { term: 'Validate on slices', def: 'Compare the challenger with the champion on important slices — regions, devices, customer types, rare classes — not just overall.', eg: 'a model can win overall and lose badly on a critical minority segment' }, 'Validation must go beyond overall numbers. Compare the challenger with the champion on important slices: regions, device types, customer groups and rare but critical classes. A model can win on average while losing badly on a small but important segment, and slice checks catch that before users do.'),
      S('definition', 'GitOps', { term: 'GitOps', def: 'The desired state of every environment lives in Git. An automated agent (e.g. Argo CD, Flux) continuously makes the cluster match it; deploying = merging a pull request.', eg: 'rollback = revert the commit' }, 'GitOps takes this further. The desired state of every environment, including which model version is deployed, lives in a Git repository. An automated agent such as Argo CD or Flux continuously makes the cluster match it. Deploying means merging a reviewed pull request, and rolling back means reverting it.'),
      S('definition', 'Infrastructure as code', { term: 'Infrastructure as code', def: 'Describe servers, clusters, pipelines and permissions in versioned files (e.g. Terraform, Kubernetes manifests) instead of manual clicks.', eg: 'environments can be reviewed, reproduced and rolled back like code' }, 'Infrastructure itself should be code. Servers, clusters, pipelines and permissions are described in versioned files, such as Terraform configurations and Kubernetes manifests, instead of manual clicks in a console. Environments can then be reviewed, reproduced and rolled back just like application code.'),
      S('lineage', 'Audit trail', {}, 'All this automation leaves an audit trail. For every model in production, you can see which code, data and parameters produced it, which tests and gates it passed, who approved it and when it was deployed. In regulated industries such as finance and healthcare, this traceability is often a legal requirement.'),
      S('table', 'Strategies summary', { head: 'Deployment strategies at a glance', cols: ['Strategy', 'User risk', 'Rollback', 'Best for'], widths: [1, 1, 1, 1.8], rows: [['Shadow', 'none', 'not needed', 'catching crashes and skew'], ['Canary', 'small, growing', 'automatic', 'most model updates'], ['Blue–green', 'all at once', 'instant switch', 'infrastructure changes'], ['A/B test', 'split traffic', 'end the test', 'measuring business impact']] }, 'In summary: shadow deployments carry no user risk and catch crashes and skew. Canaries expose a small, growing share with automatic rollback and suit most model updates. Blue green switches everyone at once with instant rollback, and A B tests measure real business impact.'),
      S('bullets', 'Pitfalls', { head: 'Common pitfalls', items: ['Flaky tests — random seeds and tiny test sets cause false alarms', 'Gates too loose — or on the wrong metric', 'No segment checks — averages hide group regressions', 'Big-bang releases — everything changed at once'] }, 'Watch for pitfalls. Flaky tests, caused by unfixed seeds or tiny test sets, erode trust in the pipeline. Gates that are too loose, or on the wrong metric, let bad models through. Averages can hide regressions for particular groups. And big bang releases make it impossible to tell which change caused a problem.'),
      S('question', 'Pause and think', { q: 'Your model-quality test fails randomly about one run in ten, even with no changes. What should you do?', a: 'Fix the flakiness: set random seeds, use a larger fixed evaluation set, and set thresholds that account for measurement noise. Never just re-run until it passes.' }, 'Pause and think. Your model quality test fails randomly about one run in ten, even with no changes. What should you do? Fix the flakiness: set random seeds, use a larger fixed evaluation set, and choose thresholds that allow for measurement noise. Never simply re run until it passes.'),
      S('bullets', 'Recap', { style: 'recap', items: ['CI tests code, data and models; CT retrains automatically', 'Quality gates block weak or regressing models', 'Champion–challenger: replace only when clearly better', 'Shadow → canary (with auto-rollback) → full rollout', 'Build once, deploy many; always be able to roll back'] }, 'To recap. Continuous integration tests code, data and models, and continuous training retrains them automatically. Quality gates block weak models. Champions are replaced only by clearly better challengers. Release gradually, from shadow to canary to full rollout, build once and deploy many, and always keep rollback ready.')
    ],
    takeaways: ['ML adds Continuous Training (CT) to CI/CD because models can go stale without code changes.', 'Test code, data, model quality (overall and per segment), behaviour (invariance, directional) and integration.', 'Quality gates automatically block models that miss thresholds or regress versus production.', 'Champion–challenger evaluation replaces the production model only when a new one is clearly better.', 'Shadow deployments, canary releases with automatic rollback, blue–green switches and A/B tests make releases safe.', 'Build one immutable artefact, promote it through environments, and keep rollback fast and practised.'],
    quiz: [
      { q: 'What does Continuous Training (CT) add to CI/CD?', a: ['Faster laptops', 'Automatic retraining when new data arrives or drift is detected', 'Manual approvals only', 'Tokenisation'], c: 1, why: 'Models go stale as data changes.' },
      { q: 'In a shadow deployment, whose predictions do users see?', a: ['The new model’s', 'The old model’s only', 'Both', 'Neither'], c: 1, why: 'The new model runs silently for comparison.' },
      { q: 'A canary release…', a: ['Switches all traffic at once', 'Gradually increases the share of traffic to the new version while monitoring', 'Never uses real traffic', 'Deletes the old version first'], c: 1, why: '1% → 5% → 25% → … with rollback.' },
      { q: 'What is an invariance test?', a: ['Checking that irrelevant input changes do not change the output', 'Checking training speed', 'Checking that the model changes every day', 'A load test'], c: 0, why: 'From behavioural (CheckList-style) testing.' },
      { q: 'What does “build once, deploy many” mean?', a: ['Rebuild the image for each environment', 'Promote the same tested artefact through all environments, changing only configuration', 'Deploy only once a year', 'Use one server'], c: 1, why: 'What you tested is what you ship.' }
    ],
    read: ['ci-cd-for-machine-learning', 'ab-testing-ml-models', 'model-cards-and-documentation']
  },
  {
    slug: 'monitoring-drift-and-retraining', title: 'Monitoring, Drift and Retraining', track: 'mlops', level: 'Intermediate', deep: true,
    summary: 'Why models decay and how to catch it: what to monitor, data drift vs concept drift, the population stability index, delayed labels, alerting, incident response and retraining strategies.',
    scenes: [
      S('title', 'Introduction', { title: 'Monitoring, Drift and Retraining', sub: 'Keeping models healthy after launch', track: 'MLOps & Engineering' }, 'A model is trained on a snapshot of the past, but it serves in a present that keeps changing. Customers change, markets change, sensors age and upstream systems get modified. In this deep dive we learn how to watch a model in production, detect when it drifts, and decide when to retrain.'),
      S('definition', 'Model decay', { term: 'Model decay', def: 'A deployed model’s real-world performance degrades over time because the world, or the data pipeline, changes — even though the model itself does not.', eg: 'a fraud model trained before a new payment method launches' }, 'Model decay is the gradual, or sometimes sudden, loss of real world performance after deployment. The model itself does not change, but the world does, or an upstream pipeline does. A fraud model trained before a new payment method launches may simply not recognise the new patterns.'),
      S('monitor', 'A monitoring dashboard', {}, 'Here is a monitoring dashboard over thirty days. Latency and error rate stay perfectly healthy throughout. But on day eighteen an upstream pipeline change breaks a feature, and the mean prediction score jumps immediately. Accuracy, which can only be measured when labels arrive three days later, confirms the damage.'),
      S('table', 'What to monitor', { head: 'Four layers of monitoring', cols: ['Layer', 'Examples', 'Available'], widths: [1, 2.2, 1], rows: [['System', 'latency, errors, throughput, CPU/GPU, memory', 'instantly'], ['Data', 'schema, missing values, feature distributions', 'instantly'], ['Predictions', 'score distribution, confidence, class mix', 'instantly'], ['Outcomes', 'accuracy, business KPIs, user feedback', 'often delayed']] }, 'Monitor four layers. System metrics such as latency and errors. Data quality and feature distributions. The distribution of predictions. And outcomes: accuracy, business metrics and user feedback. The first three are available instantly. Outcomes often arrive days or weeks later, so the earlier layers are your early warning system.'),
      S('question', 'Pause and think', { q: 'In the dashboard, why did the prediction-score panel raise the alarm before the accuracy panel?', a: 'Predictions are available instantly, while ground-truth labels arrived three days later. Input and prediction monitoring gives early warning when labels are delayed.' }, 'Pause and think. In the dashboard, why did the prediction score panel sound the alarm before the accuracy panel? Because predictions are available instantly, while the true labels arrived three days later. Watching inputs and predictions gives early warning when outcomes are delayed.'),
      S('definition', 'Data drift', { term: 'Data drift (covariate shift)', def: 'The distribution of the inputs P(x) changes, while the relationship between inputs and outcome may stay the same.', eg: 'a bank’s app becomes popular with younger customers: the age distribution shifts' }, 'Data drift, also called covariate shift, is a change in the distribution of the inputs. Perhaps a bank’s app becomes popular with younger customers, so the age distribution shifts. The underlying relationship may be unchanged, but the model now sees more of the kinds of inputs it saw least during training.'),
      S('drift', 'Measuring drift', {}, 'Here the live age distribution, in pink, slowly moves away from the training distribution, in blue. The population stability index, on the right, summarises the gap each week. It stays near zero at first, crosses the watch level of point one in week six, and passes the alert level of point two five in week eight.'),
      S('equation', 'The PSI formula', { head: 'Population Stability Index', size: 50, parts: [{ t: 'PSI', c: 'amber' }, { t: ' = Σ' }, { t: ' (aᵢ − eᵢ)', c: 'pink', note: 'Difference between actual (live) and expected (training) share in bin i' }, { t: ' · ' }, { t: 'ln(aᵢ / eᵢ)', c: 'cyan', note: 'Log of their ratio — large when a bin grows or shrinks a lot' }], below: 'Bins: usually 10 quantiles of the training data' }, 'The population stability index splits the training data into ten equal bins, then compares the share of live data falling into each bin with the expected share. For each bin it multiplies the difference by the log of the ratio, and adds them up. It is closely related to a symmetric form of the KL divergence.'),
      S('question', 'Pause and think', { q: 'Common rules of thumb: PSI < 0.1 stable, 0.1–0.25 moderate shift, > 0.25 significant. In the animation, when would you have investigated?', a: 'Week 6 (PSI ≈ 0.10) to start watching closely; week 8 (≈ 0.27) is a clear alert to investigate and likely retrain.' }, 'Pause and think. With the common rule of thumb, below point one is stable, point one to point two five is a moderate shift, and above that is significant. When would you act in our example? Start watching closely around week six, and investigate and probably retrain once the alert fires in week eight.'),
      S('definition', 'Other drift tests', { term: 'Other drift measures', def: 'Kolmogorov–Smirnov test (continuous features), chi-squared test (categories), Jensen–Shannon distance, and model-based detectors that try to tell training data from live data.', eg: 'with huge samples, tests flag tiny harmless shifts — look at effect sizes too' }, 'Other measures are also common. The Kolmogorov Smirnov test compares continuous distributions, chi squared tests compare categories, and the Jensen Shannon distance is a bounded, symmetric divergence. Be careful with huge samples: statistical tests will flag tiny, harmless shifts, so look at effect sizes, not only p values.'),
      S('definition', 'Concept drift', { term: 'Concept drift', def: 'The relationship between inputs and outcome, P(y | x), changes — the same inputs now mean something different.', eg: 'after a policy change, the same customer profile has a different default risk' }, 'Concept drift is more dangerous: the relationship between inputs and outcome changes, so the same inputs now mean something different. After an economic shock or a policy change, a customer profile that used to be low risk may now default more often. Input distributions can look perfectly normal while the model is wrong.'),
      S('compare', 'Data vs concept drift', { head: 'Two kinds of drift', left: { title: 'Data drift', items: ['P(x) changes', 'Visible in inputs immediately', 'Model may still be right'], color: 'cyan' }, right: { title: 'Concept drift', items: ['P(y | x) changes', 'Invisible in inputs', 'Needs labels (or proxies) to detect'], color: 'pink' } }, 'In short, data drift changes what inputs look like. It is visible immediately, and the model may still be correct. Concept drift changes what inputs mean. It is invisible in the inputs, so detecting it needs outcome labels, or good proxies for them. Monitoring must cover both.'),
      S('question', 'Pause and think', { q: 'Fraudsters change tactics after your model blocks their old pattern. Which kind of drift is this?', a: 'Concept drift, often adversarial: similar-looking transactions now have a different relationship to fraud. Expect it, monitor outcomes closely and retrain frequently.' }, 'Pause and think. Fraudsters change their tactics after your model starts blocking their old pattern. Which kind of drift is this? Concept drift, and adversarial concept drift at that: transactions that look normal now carry a different risk. Expect it, watch outcomes closely and retrain frequently.'),
      S('definition', 'Label shift', { term: 'Label (prior) shift', def: 'The frequency of outcomes P(y) changes — for example fraud becomes more common — while each class still looks the same.', eg: 'recalibrate thresholds or probabilities; the ranking may still be fine' }, 'A third kind is label shift: the frequency of outcomes changes, perhaps fraud becomes twice as common, while each class still looks the same. Rankings may remain good, but predicted probabilities and decision thresholds become miscalibrated, so recalibration is often enough.'),
      S('definition', 'Calibration', { term: 'Calibration drift', def: 'Check that predicted probabilities still match observed frequencies: of cases scored 0.7, about 70% should be positive.', eg: 'ranking can stay good while probabilities become badly miscalibrated' }, 'Also monitor calibration: whether predicted probabilities still match reality. Of all the cases scored at seventy percent risk, about seventy percent should turn out positive. After label shift, rankings may stay good while probabilities become badly wrong, which matters whenever decisions use thresholds or expected costs.'),
      S('question', 'Pause and think', { q: 'Every December your drift alerts fire for a retail model, then quietly stop in January. What is going on, and how should you adapt the monitoring?', a: 'Seasonality, not a broken model. Compare with the same period last year or with a seasonally adjusted baseline, and consider seasonal features in the model.' }, 'Pause and think. Every December your drift alerts fire for a retail model, then quietly stop in January. What is happening? Seasonality, not a broken model. Compare with the same period last year, or a seasonally adjusted baseline, and consider giving the model seasonal features.'),
      S('definition', 'Delayed labels', { term: 'Delayed or missing labels', def: 'True outcomes may arrive days, months or never (loan default, churn). Use proxies — clicks, complaints, manual reviews — and prediction monitoring in the meantime.', eg: 'label a small random sample by hand each week for an unbiased estimate' }, 'Outcomes are often delayed. Whether a loan defaults may take months, and some outcomes are never observed at all. In the meantime, use proxies such as complaints, overrides by staff or quick user feedback, and label a small random sample by hand each week to get an unbiased estimate of accuracy.'),
      S('definition', 'Alerting', { term: 'Alerting', def: 'Alert on symptoms that matter to users, with thresholds tuned to avoid noise. Route alerts to an owner with a runbook.', eg: 'too many false alarms → alert fatigue → real alerts get ignored' }, 'Alerts turn monitoring into action. Alert on symptoms that matter, with thresholds tuned to avoid noise, and route each alert to a named owner with a runbook describing what to check. Too many false alarms cause alert fatigue, and then the one real alert gets ignored.'),
      S('definition', 'Service level objectives', { term: 'SLOs for ML', def: 'Targets such as “p95 latency < 200 ms”, “99.9% availability”, “weekly sampled accuracy ≥ 0.9” — with an error budget for how much violation is tolerable.', eg: 'SLOs turn “the model feels worse” into measurable commitments' }, 'Service level objectives make expectations explicit: for example, ninety fifth percentile latency under two hundred milliseconds, ninety nine point nine percent availability, and weekly sampled accuracy of at least point nine. An error budget says how much violation is tolerable before work must stop to fix reliability.'),
      S('flow', 'Incident response', { head: 'When an alert fires', nodes: [['a', 'Alert', 150, 330, 'red'], ['t', 'Triage', 400, 330, 'amber', 'real? how bad?'], ['m', 'Mitigate', 660, 330, 'lime', 'rollback / fallback'], ['rc', 'Root cause', 920, 330, 'violet', 'data? code? world?'], ['pm', 'Post-mortem', 1130, 330, 'cyan', 'blameless, add tests']], edges: [['a', 't'], ['t', 'm'], ['m', 'rc'], ['rc', 'pm'], ['pm', 't', 'better alerts', 70]], steps: ['An alert fires', 'Triage: is it real, and how severe?', 'Mitigate first: roll back or fall back', 'Then find the root cause: data, code or the world?', 'Write a blameless post-mortem and add tests', 'Improve alerts so it is caught sooner next time'] }, 'When an alert fires, triage it: is it real, and how severe? Mitigate first, by rolling back or falling back to a simpler model. Then find the root cause: a data problem, a code change, or a genuine change in the world. Finish with a blameless post mortem that adds tests and better alerts.'),
      S('rollout', 'Rollback as mitigation', { mode: 'rollback' }, 'Rollback is the fastest mitigation. Here a new version’s error rate climbs past its threshold during a canary release, and traffic automatically returns to the previous version. Keeping the last good model ready to serve turns a potential outage into a minor blip.'),
      S('definition', 'Retraining strategies', { term: 'When to retrain', def: 'Scheduled (e.g. weekly), triggered (drift or performance alerts), or online/incremental learning that updates continuously.', eg: 'choose by how fast the world changes and how costly retraining is' }, 'How often should you retrain? Scheduled retraining, such as weekly, is simple and predictable. Triggered retraining responds to drift or performance alerts. Online learning updates the model continuously as data arrives. The right choice depends on how fast the world changes and how costly and risky retraining is.'),
      S('plot', 'Retraining in action', { head: 'Accuracy over 12 weeks (illustrative)', x: [0, 12], y: [0.75, 0.95], xstep: 1, ystep: 0.05, fns: [{ f: '0.92 - 0.012 * x', c: 'red', label: 'never retrained', lx: 11.5, dy: 22 }, { f: '0.92 - 0.012 * (x - 3 * floor(x / 3))', c: 'lime', label: 'retrained every 3 weeks', lx: 11.2, dy: -26 }], xl: 'weeks since first deployment', note: 'Regular retraining restores accuracy each cycle — the sawtooth pattern.' }, 'This illustration shows the effect. A model that is never retrained slowly loses accuracy week after week. A model retrained every three weeks produces a sawtooth: accuracy slips between retrains, then recovers each time fresh data is incorporated.'),
      S('question', 'Pause and think', { q: 'Why not simply retrain every day, just to be safe?', a: 'Cost, and risk: every retrain can introduce new bugs or regressions, needs validated fresh labels, and adds operational load. Retrain as often as the drift requires, always through the same gates.' }, 'Pause and think. Why not simply retrain every day, just to be safe? Retraining costs compute, needs fresh validated labels, and every new model is a chance to introduce a bug or regression. Retrain as often as the drift requires, and always through the same quality gates.'),
      S('definition', 'Backtesting', { term: 'Backtesting a retraining policy', def: 'Replay history: at each past date, train only on data available then, and measure performance on what came next. Compare retraining schedules before adopting one.', eg: 'answers “would weekly retraining really have helped?” with evidence' }, 'How do you choose a retraining schedule? Backtest it. Replay history: at each past date, train only on data available at that time, then measure performance on what came next. Comparing weekly, monthly and drift triggered retraining this way turns a guess into evidence.'),
      S('serving', 'System health still matters', {}, 'Do not forget the system layer. Here traffic, capacity and latency are tracked through a day. A burst around midday pushes latency above the objective before the autoscaler catches up. Many model incidents turn out to be plain infrastructure problems, so system and model monitoring belong on the same dashboard.'),
      S('definition', 'Fairness over time', { term: 'Monitoring by segment', def: 'Track metrics separately for important groups (regions, devices, demographics where lawful). Overall averages can hide a collapse for one group.', eg: 'accuracy stable overall, but falling sharply for a new mobile app version' }, 'Monitor important segments separately: regions, devices, customer types and, where lawful and appropriate, demographic groups. An overall average can stay flat while performance collapses for one group, such as users of a new app version. Segment monitoring also supports fairness commitments.'),
      S('code', 'A drift check', { head: 'Computing PSI with NumPy', file: 'drift.py', lines: ['import numpy as np', '', 'def psi(expected, actual, bins=10):', '    edges = np.quantile(expected, np.linspace(0, 1, bins + 1))', '    edges[0], edges[-1] = -np.inf, np.inf', '    e = np.histogram(expected, edges)[0] / len(expected)', '    a = np.histogram(actual, edges)[0] / len(actual)', '    e, a = np.clip(e, 1e-4, None), np.clip(a, 1e-4, None)', '    return float(np.sum((a - e) * np.log(a / e)))', '', 'if psi(train_age, live_age) > 0.25:', '    alert("age distribution drifted")'], hl: [[3, 4], [5, 6], [7, 8], [10, 11]], notes: ['Bin edges from training-data quantiles', 'Share of training and live data in each bin', 'Avoid log(0), then sum the PSI terms', 'Alert when the index crosses the threshold'] }, 'A drift check fits in a few lines. Build bin edges from the training data’s quantiles, compute the share of training and live data in each bin, guard against zeros, and sum the PSI terms. When the index crosses the alert threshold, notify the owner. Libraries such as Evidently package many such checks.'),
      S('definition', 'Logging for monitoring', { term: 'Prediction logging', def: 'Log inputs, predictions, model version and request metadata (sampled if volume is huge), with privacy protection, so they can be joined with outcomes later.', eg: 'without logs, you cannot compute drift or accuracy after the fact' }, 'All of this depends on logging. Record inputs, predictions, the model version and request metadata, sampled if volume is huge, and protect personal data. Later these logs are joined with outcomes to compute accuracy. Without them, drift and accuracy simply cannot be measured after the fact.'),
      S('bullets', 'Best practices', { head: 'Monitoring best practices', items: ['Monitor all four layers — system, data, predictions, outcomes', 'Compare with a training baseline — not just last week', 'Alert on what matters — with owners and runbooks', 'Keep rollback and fallback ready', 'Retrain through the same gates as any release'] }, 'To summarise the practice. Monitor all four layers. Compare live data with the training baseline, not only with last week, to catch slow drift. Alert on what matters, with owners and runbooks. Keep rollback and fallbacks ready. And retrain through the same gates as any other release.'),
      S('bullets', 'Recap', { style: 'recap', items: ['Models decay because the world and pipelines change', 'Watch system, data, predictions and outcomes', 'Data drift: P(x) changes; concept drift: P(y | x) changes', 'PSI > 0.25 is a common alert threshold', 'Mitigate first (rollback), then fix root causes and retrain'] }, 'To recap. Models decay because the world and the data pipelines change. Monitor systems, data, predictions and outcomes. Data drift changes the inputs, while concept drift changes what they mean. PSI summarises distribution shift, and when things go wrong, mitigate first, then fix the root cause and retrain.')
    ],
    takeaways: ['Deployed models decay as the world or upstream pipelines change, even when their code does not.', 'Monitor four layers: system, data, predictions and outcomes; outcomes are often delayed.', 'Data drift changes P(x); concept drift changes P(y | x) and needs labels or proxies to detect; label shift changes P(y).', 'PSI compares binned live vs training distributions; rules of thumb: < 0.1 stable, > 0.25 significant.', 'Respond to incidents by mitigating first (rollback/fallback), then root cause and a blameless post-mortem.', 'Retrain on a schedule or on triggers, through the same quality gates, and monitor key segments separately.'],
    quiz: [
      { q: 'Which drift changes the relationship between inputs and outcome?', a: ['Data drift', 'Concept drift', 'Label shift', 'Latency drift'], c: 1, why: 'Concept drift: P(y | x) changes.' },
      { q: 'Why monitor prediction distributions even when you monitor accuracy?', a: ['They are prettier', 'They are available instantly, while labels may arrive much later', 'Accuracy is never useful', 'They replace system metrics'], c: 1, why: 'Early warning when labels are delayed.' },
      { q: 'A PSI of 0.4 on a key feature suggests…', a: ['No change', 'A significant distribution shift worth investigating', 'The model is perfect', 'Latency problems'], c: 1, why: 'Above ~0.25 is usually treated as significant.' },
      { q: 'When an alert shows the new model is failing, the FIRST step is usually to…', a: ['Write a paper', 'Mitigate: roll back or fall back', 'Delete the logs', 'Retrain immediately without checks'], c: 1, why: 'Stop the harm, then investigate.' },
      { q: 'Why monitor metrics by segment?', a: ['To slow down dashboards', 'Averages can hide a collapse for one group', 'It is required by Docker', 'To reduce data'], c: 1, why: 'Segment views reveal hidden regressions.' }
    ],
    read: ['model-monitoring-and-drift', 'ci-cd-for-machine-learning', 'fairness-metrics']
  },
  {
    slug: 'ab-testing-and-responsible-ml-in-production', title: 'A/B Testing and Responsible ML in Production', track: 'mlops', level: 'Advanced', deep: true,
    summary: 'Measure real impact and operate responsibly: online vs offline evaluation, A/B test design, significance and the peeking trap, sample sizes, model cards, fairness, privacy, explainability and governance.',
    scenes: [
      S('title', 'Introduction', { title: 'A/B Testing and Responsible ML', sub: 'Measuring real impact — and doing it right', track: 'MLOps & Engineering' }, 'How do you know a new model actually helps people, rather than just scoring better on a test set? And how do you make sure it is fair, private and accountable once it touches real lives? This deep dive covers online experiments and the practices of responsible machine learning in production.'),
      S('compare', 'Offline vs online', { head: 'Offline vs online evaluation', left: { title: 'Offline', items: ['Historical data, held-out test set', 'Fast, cheap, safe', 'Measures proxies (accuracy, AUC)'], color: 'cyan' }, right: { title: 'Online', items: ['Live users, real decisions', 'Slower, carries some risk', 'Measures what matters (revenue, retention)'], color: 'lime' } }, 'Offline evaluation uses historical data and a held out test set. It is fast, cheap and safe, but it measures proxies such as accuracy. Online evaluation uses live users and real decisions. It is slower and carries some risk, but it measures what actually matters: engagement, revenue, retention or better outcomes.'),
      S('question', 'Pause and think', { q: 'A new recommender improves offline accuracy by 3% but reduces time spent on the site. How can that happen?', a: 'Offline data reflects the OLD system’s choices (only shown items have feedback), accuracy may not match user value, and recommendations change behaviour. Only an online test reveals the real effect.' }, 'Pause and think. A new recommender improves offline accuracy by three percent, yet users spend less time on the site. How? Historical data only contains feedback on items the old system chose to show, accuracy is not the same as user value, and new recommendations change behaviour. Only an online test reveals the real effect.'),
      S('definition', 'A/B testing', { term: 'A/B test (randomised controlled experiment)', def: 'Randomly assign users to control (A, current model) or treatment (B, new model); compare a pre-chosen metric. Randomisation makes the groups comparable, so differences are caused by the model.', eg: 'the same method used in clinical trials' }, 'An A B test is a randomised controlled experiment. Users are randomly assigned to control, which gets the current model, or treatment, which gets the new one, and a pre chosen metric is compared. Because assignment is random, the groups are alike in every other way, so a difference can be attributed to the model.'),
      S('pipeline', 'Designing a test', { head: 'Designing an A/B test', steps: ['Hypothesis', 'Metrics', 'Sample size', 'Randomise', 'Run', 'Decide'], desc: ['“Model B increases conversion.”', 'One primary metric, plus guardrail metrics that must not get worse.', 'Compute how many users are needed to detect the effect you care about.', 'Assign by user, consistently, and check that group sizes match.', 'Run for the planned duration — covering full weekly cycles.', 'Analyse once, at the end, as planned.'] }, 'A good test is designed before it starts. State a hypothesis. Choose one primary metric plus guardrail metrics that must not get worse, such as latency or complaints. Compute the required sample size. Randomise consistently by user. Run for the planned duration, covering full weekly cycles, and analyse once, as planned.'),
      S('definition', 'Guardrail metrics', { term: 'Guardrail metrics', def: 'Metrics that must not degrade even if the primary metric improves: latency, errors, unsubscribe rate, complaints, fairness across groups.', eg: 'a model that raises clicks but doubles complaints should not ship' }, 'Guardrail metrics protect against winning the wrong way. A model that raises clicks but doubles complaints, slows the page or harms one group of users should not ship. Guardrails are checked alongside the primary metric, and a violation blocks the launch even when the headline number looks great.'),
      S('abtest', 'Running the test', {}, 'Here is a fourteen day test with seven hundred users per day in each group. The current model converts about ten percent of users, and the new model slightly more. The confidence intervals shrink as data accumulates, and the p value, on the right, wanders before settling below point zero five by the planned end.'),
      S('equation', 'The test statistic', { head: 'Two-proportion z-test', size: 44, parts: [{ t: 'z', c: 'amber' }, { t: ' = ' }, { t: '(p_B − p_A)', c: 'green', note: 'Observed difference in conversion rates' }, { t: ' / ' }, { t: '√(p(1 − p)(1/n_A + 1/n_B))', c: 'cyan', note: 'Standard error of the difference (p = pooled rate)' }], below: 'Large |z| → a difference unlikely to be due to chance → small p-value' }, 'The analysis uses a two proportion z test. Divide the observed difference in conversion rates by its standard error, computed from the pooled rate and both sample sizes. A large z means the difference would be unlikely if the models were truly equal, which corresponds to a small p value.'),
      S('definition', 'p-values', { term: 'p-value and significance', def: 'The probability of seeing a difference at least this large if there were truly no difference. p < 0.05 is a common, somewhat arbitrary threshold.', eg: 'p is NOT the probability that B is better' }, 'A p value is the probability of seeing a difference at least this large if the two models were truly equal. A common threshold is point zero five. It is not the probability that the new model is better, and a significant result is not necessarily a large or important one, so always report the effect size with its interval.'),
      S('question', 'The peeking trap', { q: 'In our test, p first dipped below 0.05 on day 5, then rose above it again. What if the team had stopped on day 5?', a: 'They would have declared victory on noise. Checking repeatedly and stopping at the first p < 0.05 (“peeking”) greatly inflates false positives. Decide the duration in advance, or use sequential methods designed for continuous monitoring.' }, 'Pause and think. In our test, the p value dipped below point zero five on day five, then rose above it again. What if the team had stopped on day five? They would have declared victory on noise. Repeatedly checking and stopping at the first significant result greatly inflates false positives. Decide the duration in advance.'),
      S('equation', 'Sample size', { head: 'How many users do you need? (rule of thumb)', size: 50, parts: [{ t: 'n per group', c: 'amber' }, { t: ' ≈ ' }, { t: '16 σ²', c: 'cyan', note: 'σ² = variance of the metric; for a conversion rate p, σ² = p(1 − p)' }, { t: ' / δ²', c: 'pink', note: 'δ = the smallest effect worth detecting' }], below: 'For about 80% power at a 5% significance level' }, 'Before starting, compute the sample size. A handy rule of thumb for about eighty percent power at the five percent level is sixteen times the variance divided by the square of the smallest effect you care about. Small effects need huge samples, because the required size grows with one over the effect squared.'),
      S('question', 'Compute it', { q: 'Baseline conversion is 10%. How many users per group are needed to detect an absolute lift of 1 percentage point?', a: 'σ² = 0.1 × 0.9 = 0.09; n ≈ 16 × 0.09 / 0.01² = 14,400 users per group.' }, 'Let us compute one. Baseline conversion is ten percent, and we want to detect a lift of one percentage point. The variance is point one times point nine, which is point zero nine. Sixteen times point zero nine divided by point zero one squared gives about fourteen thousand four hundred users per group.'),
      S('definition', 'Pitfalls', { term: 'Validity threats', def: 'Novelty effects, seasonality, sample-ratio mismatch (groups not the size you planned), interference between users, and testing many metrics at once.', eg: 'if groups should be 50/50 but are 52/48, something is broken — investigate before trusting results' }, 'Many things can invalidate a test. Users may react to novelty, which fades. Weekly and seasonal patterns bias short tests. A sample ratio mismatch, groups that are not the planned size, signals a bug in assignment or logging. Users can influence each other, and testing many metrics at once produces false positives.'),
      S('definition', 'Multiple comparisons', { term: 'Multiple testing', def: 'Checking 20 metrics at p < 0.05 gives about one false “win” by chance. Pre-register one primary metric, or correct (e.g. Bonferroni: α / number of tests).', eg: '“the new model improved engagement for left-handed users on Tuesdays” — probably noise' }, 'Beware multiple comparisons. If you check twenty metrics, or twenty segments, at the point zero five level, you expect about one false win by pure chance. Pre register a single primary metric, and correct for the others, for example with the Bonferroni method, which divides the threshold by the number of tests.'),
      S('definition', 'Long-term effects', { term: 'Holdouts and long-term effects', def: 'Keep a small, long-lived holdout group on the old experience to measure long-term effects such as retention, fatigue or trust.', eg: 'a model that boosts clicks this week may erode satisfaction over months' }, 'Some effects appear only slowly. A model that boosts clicks this week might erode satisfaction or trust over months. Keeping a small, long lived holdout group on the old experience lets you measure these long term effects, and reveals whether many small wins really add up.'),
      S('definition', 'Faster alternatives', { term: 'Interleaving and bandits', def: 'Interleaving mixes two rankers’ results in one list and sees which gets more clicks — often far more sensitive than A/B tests. Bandits shift traffic to the better variant during the test.', eg: 'common for search and recommendation ranking' }, 'For ranking systems, interleaving is a powerful alternative: results from both rankers are mixed into one list, and whichever gets more clicks wins, which is often far more sensitive than a split test. Bandits, covered in the reinforcement learning track, shift traffic towards the better variant while the test is still running.'),
      S('definition', 'Model cards', { term: 'Model cards', def: 'A short, standard document for each model: intended use and users, training data, evaluation (overall and by group), limitations, ethical considerations and contacts.', eg: 'proposed by Mitchell et al. (2019); now common practice' }, 'Now to responsible operation. A model card, proposed in 2019, is a short standard document for every model. It states the intended use and users, the training data, evaluation results overall and by group, known limitations, ethical considerations and who to contact. It helps everyone use the model appropriately.'),
      S('table', 'A model card', { head: 'Model card: churn-risk model v7 (example)', cols: ['Section', 'Content'], widths: [1, 2.6], rows: [['Intended use', 'prioritise retention offers; not for pricing or credit decisions'], ['Data', 'Jan 2023 – Jun 2025 customer records, EU region'], ['Performance', 'AUC 0.86 overall; 0.84–0.87 across age bands'], ['Limitations', 'untested on business accounts; weaker for customers under 3 months'], ['Owner', 'retention-ml team; reviewed quarterly']] }, 'Here is an example. The card says the churn model is for prioritising retention offers, and must not be used for pricing or credit. It lists the data period and region, performance overall and across age bands, known weaknesses such as new customers, and the team that owns it and reviews it every quarter.'),
      S('definition', 'Fairness', { term: 'Fairness metrics', def: 'Demographic parity: similar positive rates across groups. Equal opportunity: similar true-positive rates. Calibration: scores mean the same for every group.', eg: 'these can conflict — choose with stakeholders based on the harm at stake' }, 'Fairness can be measured in several ways. Demographic parity asks for similar positive decision rates across groups. Equal opportunity asks for similar true positive rates. Calibration asks that a given score means the same risk for everyone. These can conflict mathematically, so choose with stakeholders, based on the harms at stake.'),
      S('confusion', 'Errors by group', {}, 'Fairness analysis starts from confusion matrices computed separately for each group. If one group suffers far more false negatives, for example qualified applicants being rejected, the model harms that group even if overall accuracy looks excellent. Compare error types, not just accuracy.'),
      S('question', 'Pause and think', { q: 'A hiring screen has equal accuracy for two groups, but rejects qualified candidates from group B twice as often. Is it fair?', a: 'Not under equal opportunity: the false-negative rate differs, so qualified people in group B are harmed more. Equal accuracy can hide unequal error types.' }, 'Pause and think. A hiring screen has equal accuracy for two groups, but rejects qualified candidates from group B twice as often. Is it fair? Not by the equal opportunity standard. The false negative rate differs, so qualified people in group B are harmed more. Equal accuracy can hide very unequal errors.'),
      S('definition', 'Explainability', { term: 'Explainability', def: 'Global: which features drive the model overall. Local: why this particular prediction (e.g. SHAP values, counterfactual explanations).', eg: '“Your application would have been approved if your debt ratio were below 35%.”' }, 'People affected by automated decisions often deserve an explanation. Global explanations show which features drive the model overall. Local explanations, such as SHAP values or counterfactuals, explain a single prediction, for example: your application would have been approved if your debt ratio were below thirty five percent.'),
      S('definition', 'Privacy', { term: 'Privacy in production', def: 'Minimise and protect personal data, control access, set retention limits, and consider privacy-preserving techniques such as differential privacy and federated learning.', eg: 'models can memorise and leak training data if not protected' }, 'Privacy must be designed in. Collect the minimum personal data, protect and restrict access to it, and delete it on schedule. Models can memorise and leak training examples, so sensitive applications consider techniques such as differential privacy, which adds calibrated noise, or federated learning, which keeps data on devices.'),
      S('definition', 'Governance and regulation', { term: 'Governance', def: 'Clear ownership, risk assessment before launch, documentation, human oversight, audit trails and incident processes. Regulations such as the EU AI Act classify systems by risk.', eg: 'high-risk uses (hiring, credit, medical) face stricter obligations' }, 'Governance ties it together: clear ownership, risk assessment before launch, documentation, human oversight, audit trails and incident processes. Regulation is catching up. The European Union’s AI Act, adopted in 2024, classifies systems by risk, with stricter obligations for high risk uses such as hiring, credit and medical devices.'),
      S('definition', 'Human oversight', { term: 'Human in the loop', def: 'Route uncertain or high-stakes cases to people, let affected users contest decisions, and monitor overrides.', eg: 'automation bias: people over-trust machine outputs — design reviews carefully' }, 'For high stakes decisions, keep people in the loop. Route uncertain or unusual cases to human reviewers, give affected users a way to contest decisions, and track how often reviewers override the model. Beware automation bias, the tendency to over trust machine output, which can make oversight a rubber stamp.'),
      S('lineage', 'Accountability', {}, 'Accountability requires traceability. For any decision, you should be able to say which model version made it, which code and data produced that model, and who approved its release. The lineage we built for reproducibility doubles as the audit trail that regulators and affected people may ask for.'),
      S('bullets', 'Environmental cost', { head: 'Cost and environmental impact', items: ['Measure energy and cost per training run and per 1,000 predictions', 'Prefer smaller or distilled models when quality allows', 'Schedule big jobs in efficient, low-carbon regions and times', 'Avoid needless retraining and oversized experiments'] }, 'Responsibility also includes cost and environmental impact. Measure energy and cost per training run and per thousand predictions. Prefer smaller or distilled models when quality allows. Schedule large jobs in efficient, low carbon regions and times, and avoid needless retraining and oversized experiments.'),
      S('flow', 'A responsible release', { head: 'A responsible release process', nodes: [['r', 'Risk assessment', 170, 330, 'amber'], ['e', 'Evaluation', 450, 330, 'cyan', 'overall + by group'], ['d', 'Documentation', 730, 330, 'violet', 'model card'], ['a', 'Approval', 1010, 330, 'lime', 'owner + reviewers'], ['m', 'Monitor & review', 730, 520, 'pink', 'drift, fairness, complaints']], edges: [['r', 'e'], ['e', 'd'], ['d', 'a'], ['a', 'm', 'launch'], ['m', 'r', 'periodic review', 60]], steps: ['Assess risks and affected people before building', 'Evaluate overall and for each important group', 'Document in a model card', 'Get explicit approval from the owner and reviewers', 'After launch, monitor drift, fairness and complaints', 'Review periodically and reassess the risks'] }, 'A responsible release follows a loop. Assess risks and who could be affected. Evaluate overall and by group. Document the model in a model card. Get explicit approval from the owner and reviewers. After launch, monitor drift, fairness and complaints, and review periodically, reassessing the risks as the world changes.'),
      S('bullets', 'Checklist', { head: 'Responsible ML checklist', items: ['Intended use and misuse written down', 'Performance and errors checked by group', 'Personal data minimised and protected', 'Explanations and appeal paths for affected people', 'Owner, monitoring and review schedule in place'] }, 'Here is a short checklist. Is the intended use, and misuse, written down? Are performance and errors checked by group? Is personal data minimised and protected? Can affected people get an explanation and appeal? And is there a named owner, with monitoring and a review schedule? If any answer is no, the model is not ready.'),
      S('bullets', 'Recap', { style: 'recap', items: ['Offline metrics are proxies; A/B tests measure real impact', 'Pre-register metrics, sample size and duration — no peeking', 'n ≈ 16σ²/δ² per group for ~80% power', 'Model cards, fairness by group, privacy, explanations', 'Governance: ownership, oversight, audit trails, regulation'] }, 'To recap. Offline metrics are proxies, and randomised A B tests measure real impact. Fix metrics, sample size and duration in advance, and do not peek. Use the sixteen sigma squared over delta squared rule for sample sizes. And operate responsibly with model cards, fairness checks, privacy, explanations and clear governance.')
    ],
    takeaways: ['Offline metrics are proxies; randomised online experiments (A/B tests) measure real impact.', 'Design tests up front: hypothesis, primary and guardrail metrics, sample size, duration, randomisation unit.', 'A p-value is P(data this extreme | no difference); stopping at the first p < 0.05 (peeking) inflates false positives.', 'Rule of thumb for ~80% power: n ≈ 16σ²/δ² per group (≈ 14,400 per group for 10% → 11%).', 'Model cards document intended use, data, performance by group and limitations.', 'Responsible ML covers fairness metrics, explainability, privacy, human oversight, governance (e.g. the EU AI Act) and environmental cost.'],
    quiz: [
      { q: 'Why is randomisation essential in an A/B test?', a: ['It speeds up the servers', 'It makes groups comparable, so differences are caused by the model', 'It hides the results', 'It reduces the sample size'], c: 1, why: 'Random assignment balances everything else.' },
      { q: 'What is “peeking”?', a: ['Looking at the code', 'Checking results repeatedly and stopping at the first significant result', 'Using a holdout set', 'Encrypting logs'], c: 1, why: 'It inflates false positives.' },
      { q: 'With baseline 10% and a 1-point lift to detect, the rule of thumb gives about…', a: ['144 users per group', '1,440', '14,400', '1.44 million'], c: 2, why: '16 × 0.09 / 0.0001 = 14,400.' },
      { q: 'Equal opportunity requires similar…', a: ['Overall accuracy', 'True-positive rates across groups', 'Numbers of users', 'Latency'], c: 1, why: 'Qualified people should be recognised equally often.' },
      { q: 'What is a model card?', a: ['A GPU', 'A short document describing a model’s intended use, data, performance and limitations', 'A login token', 'A type of test set'], c: 1, why: 'Proposed by Mitchell et al., 2019.' }
    ],
    read: ['ab-testing-ml-models', 'model-cards-and-documentation', 'fairness-metrics', 'explainable-ai-lime-shap', 'ai-regulation-and-governance']
  }
];
